window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-2/rc-1","titre":"Raisonnement clinique I","sources":[{"t":"La CIF et le processus kinésithérapique","q":"rc-01-cif-et-processus-kinesitherapique/quiz.html","f":"rc-01-cif-et-processus-kinesitherapique/fiche.html"},{"t":"Raisonnement clinique en conditions cardio-respiratoires","q":"rc-02-conditions-cardio-respiratoires/quiz.html","f":"rc-02-conditions-cardio-respiratoires/fiche.html"},{"t":"Introduction au raisonnement clinique","q":"rc-03-introduction-au-raisonnement-clinique/quiz.html","f":"rc-03-introduction-au-raisonnement-clinique/fiche.html"},{"t":"Cas clinique : jeune athlète, douleurs bilatérales d'épaule","q":"rc-04-cas-epaule-nageuse/quiz.html","f":"rc-04-cas-epaule-nageuse/fiche.html"},{"t":"Cas cliniques neurologiques : AVC et lésion médullaire","q":"rc-05-cas-neurologiques/quiz.html","f":"rc-05-cas-neurologiques/fiche.html"}],"questions":[{"q":"À quelle famille de classifications appartient la CIF ?","o":["À la famille des classifications internationales de l'OMS","À la nomenclature européenne des actes","Au référentiel national de kinésithérapie","À la classification de l'APTA"],"r":0,"e":"La CIF fait partie de la famille des classifications internationales de l'OMS, aux côtés notamment de l'ICHI.","s":0},{"q":"Que signifie ICHI ?","o":["International Classification of Health Instruments","Classification internationale des interventions en santé","International Core Health Index","Index de classification du handicap international"],"r":1,"e":"L'ICHI est la Classification internationale des interventions en santé, dont l'objectif est d'évaluer, améliorer, maintenir, promouvoir ou modifier la santé, le fonctionnement ou l'état de santé.","s":0},{"q":"Quels modèles la CIF permet-elle de dépasser ?","o":["Le modèle médical (la maladie) et le modèle social (la société)","Le modèle biomécanique et le modèle neurologique","Le modèle quantitatif et le modèle qualitatif","Le modèle hospitalier et le modèle libéral"],"r":0,"e":"La CIF répond à la question « incapacité ou fonctionnement ? » en dépassant l'opposition entre modèle médical, centré sur la maladie, et modèle social, centré sur la société.","s":0},{"q":"Quel est l'objectif de la CIF le plus souvent cité en premier pour la communication interprofessionnelle ?","o":["Servir de base au remboursement","Établir un langage commun pour la description de la santé et des états liés à la santé","Remplacer le diagnostic médical","Classer les interventions"],"r":1,"e":"Un des objectifs généraux est d'établir un langage commun pour la description de la santé, afin d'améliorer la communication entre différents utilisateurs.","s":0},{"q":"Quelle composante de la CIF correspond au terme « déficience » ?","o":["L'activité","La participation","Les fonctions et structures du corps","Les facteurs environnementaux"],"r":2,"e":"La déficience désigne les écarts, pertes ou problèmes des fonctions ou structures du corps.","s":0},{"q":"Quelle composante correspond au terme « limitation » ?","o":["Les structures du corps","L'activité","La participation","Les facteurs personnels"],"r":1,"e":"Les limitations d'activité sont les difficultés de l'individu à réaliser les activités.","s":0},{"q":"Quelle composante correspond au terme « restriction » ?","o":["La participation","Les fonctions du corps","L'activité","Les facteurs environnementaux"],"r":0,"e":"Les restrictions de participation sont les problèmes d'intégration de l'individu dans la société.","s":0},{"q":"Comment le cours définit-il l'activité ?","o":["L'implication de l'individu dans la société","L'exécution d'une tâche ou action réalisée par l'individu","Une fonction physiologique","Une région anatomique"],"r":1,"e":"L'activité est l'exécution d'une tâche ou action réalisée par l'individu ; la participation est l'implication de l'individu dans la société.","s":0},{"q":"De quelles deux manières les composantes du fonctionnement peuvent-elles être exprimées ?","o":["En pourcentage et en score brut","Pour indiquer des problèmes (incapacité) ou des aspects neutres (fonctionnement)","En valeurs absolues et relatives","En données subjectives et objectives"],"r":1,"e":"Elles peuvent indiquer des problèmes — déficience, limitation d'activité, restriction de participation, c'est-à-dire l'incapacité — ou des aspects non problématiques, neutres, c'est-à-dire le fonctionnement.","s":0},{"q":"Comment un facteur environnemental peut-il être qualifié ?","o":["Comme facilitateur ou comme barrière","Comme positif ou neutre seulement","Comme structurel ou fonctionnel","Comme personnel ou social"],"r":0,"e":"Les facteurs environnementaux sont externes à l'individu et peuvent avoir une influence positive ou négative : ils sont qualifiés de facilitateur ou de barrière.","s":0},{"q":"Pourquoi les facteurs personnels ne sont-ils pas classés dans la CIF ?","o":["Parce qu'ils sont sans importance clinique","En raison de la grande variation sociale et culturelle qui leur est associée","Parce qu'ils relèvent du secret médical","Parce qu'ils sont déjà couverts par les facteurs environnementaux"],"r":1,"e":"Les facteurs contextuels personnels ne sont pas classés dans la CIF en raison de la grande variation sociale et culturelle qui leur est associée.","s":0},{"q":"Comment sont organisés les facteurs environnementaux dans la CIF ?","o":["Par ordre alphabétique","De façon séquentielle, de l'environnement le plus immédiat de l'individu jusqu'à l'environnement général","Par ordre d'importance clinique","Par pays"],"r":1,"e":"Ils ont un impact sur toutes les composantes du fonctionnement et sont organisés de façon séquentielle, de l'environnement le plus immédiat jusqu'à l'environnement général.","s":0},{"q":"Lequel de ces éléments est un facteur contextuel INDIVIDUEL ?","o":["Les normes sociales","Les institutions","L'âge, la personnalité et l'expérience antérieure","Le milieu d'habitation"],"r":2,"e":"Les facteurs individuels sont le genre, l'âge, la personnalité et le background social, l'éducation, la profession, l'expérience antérieure et la culture ; les produits, institutions, normes sociales, milieu d'habitation, facteurs politiques et la nature relèvent de l'environnement.","s":0},{"q":"Quel chapitre des Fonctions du corps concerne le mouvement ?","o":["Le chapitre 1 : fonctions mentales","Le chapitre 4 : fonctions cardiovasculaires","Le chapitre 7 : fonctions neuro-musculo-squelettiques et liées au mouvement","Le chapitre 8 : fonctions de la peau"],"r":2,"e":"Le chapitre 7 des Fonctions du corps porte sur les fonctions neuro-musculo-squelettiques et liées au mouvement ; le chapitre 7 des Structures porte sur les structures liées au mouvement.","s":0},{"q":"Quel chapitre d'Activités et participation correspond à la mobilité ?","o":["Le chapitre 2","Le chapitre 4","Le chapitre 6","Le chapitre 9"],"r":1,"e":"Le chapitre 4 d'Activités et participation est consacré à la mobilité.","s":0},{"q":"Quel chapitre des Facteurs environnementaux traite des attitudes ?","o":["Le chapitre 1","Le chapitre 3","Le chapitre 4","Le chapitre 5"],"r":2,"e":"Les cinq chapitres des facteurs environnementaux sont : 1 produits et technologie, 2 environnement naturel, 3 soutien et relations, 4 attitudes, 5 services, systèmes et politiques.","s":0},{"q":"Quel concept fonde le diagnostic fonctionnel selon la CIF ?","o":["La multidirectionnalité, qui ne centre pas le diagnostic sur la maladie","La linéarité causale","La hiérarchie médicale","La spécialisation par organe"],"r":0,"e":"Le diagnostic fonctionnel repose sur le concept de multidirectionnalité : dans le domaine de la santé, il ne centre pas le diagnostic sur la maladie.","s":0},{"q":"De quoi se compose un diagnostic fonctionnel selon la formule du cours ?","o":["De la maladie et de ses symptômes","Des facteurs environnementaux et personnels + structures + fonctions + activité + participation","Des seules structures et fonctions du corps","Du score d'une échelle validée"],"r":1,"e":"Le diagnostic fonctionnel additionne facteurs environnementaux et facteurs personnels, structures, fonctions, activité et participation.","s":0},{"q":"Que sont les Core Sets de la CIF ?","o":["Des listes des catégories les plus fréquentes dans une condition donnée","La version complète de la classification","Un logiciel de cotation","Des questionnaires validés en langue portugaise"],"r":0,"e":"Les Core Sets sont des listes de catégories les plus fréquentes dans une condition : musculo-squelettique, neurologie, cardiorespiratoire, conditions chroniques, gériatrie ; il existe aussi des Core Sets génériques.","s":0},{"q":"Quels sont les trois niveaux d'utilisation de la CIF ?","o":["Version complète, checklist et Core Sets","Structures, fonctions et activités","Évaluation, réévaluation et bilan","Débutant, intermédiaire et avancé"],"r":0,"e":"Le cours distingue la CIF version complète, la CIF checklist et les CIF Core Sets, y compris génériques.","s":0},{"q":"À quelle composante appartient le code b710 « mobilité des articulations » ?","o":["Aux structures du corps","Aux fonctions du corps","Aux activités et participation","Aux facteurs environnementaux"],"r":1,"e":"Le préfixe b désigne les fonctions du corps : b710 mobilité des articulations, b7305 force des muscles du tronc, b28013 douleur dans le dos.","s":0},{"q":"À quelle composante appartient le code d850 « travail rémunéré » ?","o":["Aux fonctions du corps","Aux activités et participation","Aux facteurs environnementaux","Aux facteurs personnels"],"r":1,"e":"Le préfixe d désigne les activités et participation : d850 travail rémunéré, d9201 sports, d430 soulever et transporter des objets.","s":0},{"q":"À quelle composante appartient le code e310 « famille proche » ?","o":["Aux facteurs environnementaux","Aux facteurs personnels","Aux activités","Aux fonctions du corps"],"r":0,"e":"Le préfixe e désigne les facteurs environnementaux : e1101 médicaments, e310 famille proche, e355 professionnels de santé.","s":0},{"q":"De quel modèle est adapté le modèle d'évaluation et d'intervention en kinésithérapie présenté ?","o":["Du modèle de Sackett","Du Modèle de gestion du patient de Hall & Brody (1999)","Du modèle de Shumway-Cook","Du modèle biopsychosocial de Engel"],"r":1,"e":"Le modèle est adapté du Modèle de gestion du patient de Hall & Brody, 1999.","s":0},{"q":"Quelle est la deuxième étape du modèle d'évaluation et d'intervention ?","o":["L'examen subjectif et objectif","L'évaluation : interprétation des données, CIF et tableau physiopathologique","La hiérarchisation des problèmes","Le diagnostic en kinésithérapie"],"r":1,"e":"Les six étapes sont : 1 examen, 2 évaluation (interprétation des données / CIF / tableau physiopathologique), 3 hiérarchisation des principaux problèmes, 4 diagnostic kinésithérapique, 5 objectifs et pronostic, 6 plan d'intervention.","s":0},{"q":"Sur quoi porte le diagnostic en kinésithérapie ?","o":["Sur la pathologie médicale","Sur le profil fonctionnalité/incapacité : structures et fonctions, activité et participation, facteurs environnementaux","Sur le score d'une échelle unique","Sur le pronostic vital"],"r":1,"e":"Le diagnostic en kinésithérapie correspond au profil fonctionnalité/incapacité : structures et fonctions du corps, activité et participation, facteurs environnementaux.","s":0},{"q":"Que signifie le A de SMART, selon la nuance apportée par le cours ?","o":["Attainable, et aussi « Agreed Upon » : avec l'accord de tous les stakeholders","Ambitious","Analysable","Appliqué"],"r":0,"e":"Attainable signifie que la concrétisation doit être possible, et les objectifs proposés en accord avec tous les intervenants ; on parle aussi d'« Agreed Upon », consentement de tous les stakeholders.","s":0},{"q":"Que signifie le R de SMART ?","o":["Rapide","Realistic : en accord avec la disponibilité des ressources","Reproductible","Rigoureux"],"r":1,"e":"Réaliste signifie que les objectifs ne prétendent pas atteindre des buts bien au-delà de ce que les moyens permettent, mais sont en accord avec la disponibilité des ressources.","s":0},{"q":"Qu'est-ce qui distingue la PBE de la PIE sur le plan de la flexibilité ?","o":["La PBE suit de près les directives issues des preuves, la PIE utilise la preuve comme un guide et non un protocole rigide","La PBE est plus flexible que la PIE","Les deux sont également rigides","La PIE ignore les preuves scientifiques"],"r":0,"e":"La PBE suit de près les directives dérivées des preuves scientifiques ; la PIE laisse de la place aux adaptations, utilisant la preuve comme un guide et non comme un protocole rigide.","s":0},{"q":"Dans quel contexte la PIE est-elle particulièrement utile ?","o":["Quand les preuves sont abondantes et concordantes","Quand il n'y a pas beaucoup de preuves disponibles ou que les études ne couvrent pas la situation spécifique","Uniquement en recherche","Uniquement en milieu hospitalier"],"r":1,"e":"La PIE est particulièrement utile dans des contextes où il n'y a pas beaucoup de preuves scientifiques disponibles ou où les études existantes ne couvrent pas la situation spécifique.","s":0},{"q":"Le qualificateur des composantes du fonctionnement dans la CIF s'échelonne :","o":["De 0 (pas de problème) à 4 (problème complet)","De 1 à 10","De 4+ à 4−","De A à E"],"r":0,"e":"Pour les facteurs environnementaux, l'échelle est double : de 4+ (facilitateur complet) à 0, puis de 0 à 4 (barrière complète). Les facteurs personnels se cotent en influence positive, neutre ou négative.","s":0},{"q":"Comment se cotent les facteurs personnels dans la grille du cours ?","o":["De 0 à 4","En influence positive, neutre ou négative","Ils ne sont jamais cotés","Sur une échelle de 4+ à 4"],"r":1,"e":"Ils ne sont pas classés dans la CIF en raison de la grande variation sociale et culturelle, mais la grille du cours leur attribue tout de même une influence appréciée qualitativement.","s":0},{"q":"Le chapitre 4 des Fonctions du corps regroupe :","o":["Les fonctions mentales","Les fonctions cardiovasculaires, hématologiques, immunologiques et respiratoires","Les fonctions neuro-musculo-squelettiques","Les fonctions de la peau"],"r":1,"e":"Le chapitre 1 couvre les fonctions mentales, le 2 les fonctions sensorielles et la douleur, le 7 les fonctions neuro-musculo-squelettiques et liées au mouvement, le 8 la peau.","s":0},{"q":"Le chapitre 8 d'Activités et participation correspond à :","o":["La mobilité","Les soins personnels","Les grands domaines de la vie","La vie communautaire, sociale et civique"],"r":2,"e":"La mobilité est le chapitre 4, les soins personnels le 5, la vie domestique le 6, les interactions et relations interpersonnelles le 7, la vie communautaire le 9.","s":0},{"q":"Le chapitre 1 des Facteurs environnementaux traite :","o":["Des produits et technologies","De l'environnement naturel","Du soutien et des relations","Des services, systèmes et politiques"],"r":0,"e":"Suivent l'environnement naturel et les changements d'origine humaine (2), le soutien et les relations (3), les attitudes (4), puis les services, systèmes et politiques (5).","s":0},{"q":"Les facteurs environnementaux sont organisés dans la CIF :","o":["Par ordre alphabétique","De façon séquentielle, de l'environnement le plus immédiat de l'individu jusqu'à l'environnement général","Par ordre d'importance clinique","Sans organisation particulière"],"r":1,"e":"Ils ont un impact sur toutes les composantes du fonctionnement et de l'incapacité, ce qui justifie leur classement explicite — contrairement aux facteurs personnels.","s":0},{"q":"Le code s (structures du corps) du chapitre 7 concerne :","o":["Les structures du système nerveux","Les structures liées au mouvement","La peau et structures associées","Les structures cardiovasculaires"],"r":1,"e":"Il fait pendant au chapitre 7 des fonctions du corps, consacré aux fonctions neuro-musculo-squelettiques — les deux chapitres les plus directement mobilisés en kinésithérapie.","s":0},{"q":"Le code d4103 « s'asseoir » appartient à la composante :","o":["Fonctions du corps","Activités et participation","Facteurs environnementaux","Facteurs personnels"],"r":1,"e":"Le préfixe donne la composante : b pour les fonctions du corps, s pour les structures, d pour les activités et la participation, e pour les facteurs environnementaux.","s":0},{"q":"Le code e1101 « médicaments » relève :","o":["Des fonctions du corps","Des activités et participation","Des facteurs environnementaux","Des facteurs personnels"],"r":2,"e":"Il appartient au chapitre 1 des facteurs environnementaux, consacré aux produits et technologies. Les professionnels de santé sont codés e355, la famille proche e310.","s":0},{"q":"Dans la grille du cours, « estime de soi » et « style de vie » sont codés :","o":["b — fonctions du corps","d — activités et participation","e — facteurs environnementaux","fp — facteurs personnels"],"r":3,"e":"Ils n'ont pas de code CIF officiel, précisément parce que les facteurs personnels ne sont pas classés. La grille les note donc sous une mention générique.","s":0},{"q":"Le code b7305 désigne :","o":["La mobilité des articulations","La force des muscles du tronc","La douleur dans le dos","Le fait de rester debout"],"r":1,"e":"b710 correspond à la mobilité des articulations et b28013 à la douleur dans le dos. Les trois relèvent des fonctions du corps.","s":0},{"q":"La grille d'évaluation du cours porte, pour chaque catégorie :","o":["Le seul qualificateur initial","Le qualificateur initial, l'objectif visé, le qualificateur à la réévaluation et la mention « objectif atteint »","Uniquement l'objectif visé","Le diagnostic médical associé"],"r":1,"e":"Cette structure fait de la CIF un outil de suivi et non seulement de description : elle rend le progrès mesurable catégorie par catégorie.","s":0},{"q":"Les Core Sets existent notamment pour les conditions :","o":["Musculo-squelettiques, neurologiques, cardiorespiratoires, chroniques et gériatriques","Uniquement pédiatriques","Uniquement chirurgicales","Uniquement psychiatriques"],"r":0,"e":"Il existe également des Core Sets génériques. Ils constituent le troisième niveau d'utilisation, après la version complète et la checklist.","s":0},{"q":"La CIF checklist correspond :","o":["À l'ensemble des catégories","À une version abrégée destinée à la pratique","À une liste spécifique d'une pathologie","À un questionnaire patient"],"r":1,"e":"Les trois niveaux sont : version complète, checklist et Core Sets. Le choix dépend du degré de détail nécessaire et du temps disponible.","s":0},{"q":"La notion de multidirectionnalité, qui fonde le diagnostic fonctionnel, signifie que :","o":["Le diagnostic est centré sur la maladie","Le diagnostic additionne structures, fonctions, activité, participation et facteurs contextuels, sans être centré sur la maladie","Les flèches du schéma vont dans un seul sens","Le diagnostic varie selon le professionnel"],"r":1,"e":"Toutes les flèches du schéma ICF 2001 sont bidirectionnelles : une restriction de participation peut aggraver une déficience autant que l'inverse.","s":0},{"q":"Le modèle d'évaluation et d'intervention en kinésithérapie du cours est adapté :","o":["Du Guide de l'APTA","Du Modèle de gestion du patient de Hall et Brody (1999)","De la classification de Kahneman","Des Core Sets de l'OMS"],"r":1,"e":"Il enchaîne six étapes, sous réévaluation permanente, et se trouve guidé par la pratique fondée ou informée par l'évidence.","s":0},{"q":"La troisième étape du modèle d'évaluation et d'intervention est :","o":["L'évaluation","La hiérarchisation des principaux problèmes","Le diagnostic en kinésithérapie","La définition des objectifs"],"r":1,"e":"L'ordre complet : examen, évaluation, hiérarchisation, diagnostic en kinésithérapie, définition d'objectifs et pronostic, plan d'intervention.","s":0},{"q":"La cinquième étape du modèle associe :","o":["Examen subjectif et objectif","Interprétation des données et CIF","Définition d'objectifs et pronostic","Mise en œuvre du plan"],"r":2,"e":"C'est à cette étape que s'appliquent les critères SMART. Le plan d'intervention proprement dit constitue la sixième et dernière étape.","s":0},{"q":"Le diagnostic en kinésithérapie, quatrième étape du modèle, correspond :","o":["Au nom de la pathologie","Au profil fonctionnalité/incapacité : structures et fonctions, activité et participation, facteurs environnementaux","À la liste des traitements","Au pronostic"],"r":1,"e":"C'est ce qui distingue le raisonnement du kinésithérapeute de celui du médecin : l'objet n'est pas la maladie mais le fonctionnement.","s":0},{"q":"Le M de SMART exige que les objectifs soient :","o":["Motivants","Définis de façon à pouvoir être mesurés et analysés en valeurs ou volumes","Modifiables","Multiples"],"r":1,"e":"Un objectif mesurable permet de trancher objectivement s'il est atteint. Il doit refléter les divers aspects mesurables de la situation.","s":0},{"q":"Quels sont les quatre symptômes majeurs de l'examen subjectif cardio-respiratoire ?","o":["Toux, expectoration, dyspnée et thoracalgie","Fièvre, frissons, sueurs et fatigue","Douleur, œdème, rougeur et chaleur","Cyanose, hippocratisme, tirage et sifflements"],"r":0,"e":"La symptomatologie actuelle porte sur les symptômes majeurs : toux, expectoration, dyspnée et thoracalgie.","s":1},{"q":"Quelle est la première étape de l'examen objectif cardio-respiratoire ?","o":["L'auscultation pulmonaire","Quantifier les symptômes majeurs","La percussion","Les examens complémentaires"],"r":1,"e":"L'examen objectif commence par quantifier les symptômes majeurs, puis vient l'inspection, la palpation, la percussion, l'auscultation, les autres tests et les examens complémentaires.","s":1},{"q":"Pourquoi la chirurgie abdominale a-t-elle des implications respiratoires ?","o":["Essentiellement par l'induction anesthésique et par la douleur","Par l'infection du site opératoire","Par la perte sanguine","Par la position opératoire uniquement"],"r":0,"e":"Les implications respiratoires de la chirurgie abdominale sont provoquées essentiellement par l'induction anesthésique et par la douleur.","s":1},{"q":"À quoi est due l'hypoventilation du post-opératoire immédiat ?","o":["À un pneumothorax","À l'effet anesthésique résiduel, la ventilation profonde étant inhibée par la douleur de l'incision","À l'obstruction bronchique","À l'hypovolémie"],"r":1,"e":"L'hypoventilation post-opératoire immédiate est due à l'effet anesthésique résiduel, et la ventilation profonde est facilement inhibée par la douleur au niveau de l'incision.","s":1},{"q":"Quel enchaînement décrit le mécanisme des complications respiratoires post-chirurgicales ?","o":["Schéma respiratoire superficiel, alitement, dysfonction diaphragmatique, baisse de la clairance mucociliaire et de l'efficacité de la toux","Infection, fièvre, tachycardie, choc","Douleur, spasme, contracture, raideur","Anémie, hypoxie, acidose, coma"],"r":0,"e":"Le mécanisme comprend schéma respiratoire superficiel, alitement, dysfonction diaphragmatique, diminution de la clairance mucociliaire et diminution de l'efficacité de la toux, conduisant à l'hypoxémie et aux atélectasies.","s":1},{"q":"Comment le cours définit-il la pneumonie ?","o":["Une dilatation des bronches","Une réaction inflammatoire d'origine infectieuse dans les bronchioles, les alvéoles et le tissu interstitiel","Un épanchement pleural","Une fibrose de l'interstitium"],"r":1,"e":"La pneumonie est une réaction inflammatoire d'origine infectieuse dans les bronchioles, les alvéoles et le tissu interstitiel, caractérisée par une consolidation du parenchyme.","s":1},{"q":"Que devient l'air dans le parenchyme consolidé d'une pneumonie ?","o":["Il est remplacé par un exsudat inflammatoire, avec épaississement des parois alvéolaires dû à l'œdème","Il est piégé, provoquant une hyperinflation","Il est remplacé par du tissu fibreux","Il passe dans la plèvre"],"r":0,"e":"Dans la pneumonie, l'air est remplacé par un exsudat inflammatoire et il y a un épaississement des parois alvéolaires dû à l'œdème.","s":1},{"q":"Dans le cas de la patiente opérée d'une gastrectomie, quel est le problème réel n° 1 ?","o":["La diminution de la force musculaire globale","L'augmentation de la résistance des voies aériennes périphériques","La diminution de la tolérance à l'effort","Le risque de cycle d'inactivité"],"r":1,"e":"Le problème réel n° 1 est l'augmentation de la résistance des voies aériennes périphériques, due à la rétention de sécrétions par atteinte immunitaire et diminution de l'efficacité de la toux.","s":1},{"q":"À quoi est due la diminution de la mobilité diaphragmatique bilatérale dans ce cas ?","o":["À la condensation parenchymateuse","À la présence d'une cicatrice de laparotomie médiane qui conditionne l'efficacité mécanique du diaphragme","À l'alitement seul","À la chimiothérapie"],"r":1,"e":"La diminution de la mobilité diaphragmatique bilatérale est due à la cicatrice de laparotomie médiane, qui conditionne l'efficacité mécanique du diaphragme.","s":1},{"q":"À quoi est due la diminution de la mobilité costale inférieure gauche ?","o":["À la condensation parenchymateuse à la base du poumon gauche, qui conditionne la capacité de distension","À la douleur d'incision","À l'inactivité","À la perte pondérale"],"r":0,"e":"Elle est due à la condensation parenchymateuse à la base du poumon gauche, qui conditionne la capacité de distension.","s":1},{"q":"Quel est le problème POTENTIEL identifié dans ce cas ?","o":["Une récidive de la pneumonie","Le risque de développer un cycle d'inactivité avec aggravation du déconditionnement et de la faiblesse","Un pneumothorax","Une embolie pulmonaire"],"r":1,"e":"Le problème potentiel est le risque de développer un cycle d'inactivité avec aggravation du déconditionnement cardio-respiratoire et de la faiblesse, dû à l'immobilité et au non-usage favorisés par la dyspnée d'effort.","s":1},{"q":"Quelle valeur cible est fixée pour la mobilité costale inférieure gauche ?","o":["De 3 cm à 7,5 cm en 4 à 6 semaines","De 3 cm à 5 cm en 2 semaines","De 5 cm à 10 cm en 8 semaines","Aucune valeur n'est fixée"],"r":0,"e":"L'objectif 2 est de normaliser la mobilité costale inférieure gauche, de 3 cm à 7,5 cm en 4 à 6 semaines, de façon à améliorer la ventilation à la base gauche.","s":1},{"q":"Quelle est la valeur de référence du test de marche de 6 minutes chez la femme saine selon le cours ?","o":["330 m","410 m","500 m","640 m"],"r":2,"e":"La valeur de référence pour le sexe féminin chez les individus sains est de 500 m ; la patiente a parcouru 330 m.","s":1},{"q":"Que décrit le grade 5 de l'échelle de Cotes ?","o":["Marche 100 mètres, chante, monte 8 marches","Est dyspnéique au repos","Marche 500 mètres sans limitation","Ne peut sortir du lit"],"r":0,"e":"Le grade 5 de l'échelle de Cotes signifie que le patient peut marcher 100 mètres, chanter et monter 8 marches.","s":1},{"q":"Comment se formule un objectif d'intervention selon le modèle du cours ?","o":["Uniquement par la technique employée","Par une action avec valeur de départ, valeur cible et délai, suivie d'un « De façon à… » précisant le bénéfice fonctionnel","Par le diagnostic médical","Par le nombre de séances prévues"],"r":1,"e":"Chaque objectif associe une action mesurée avec valeur de départ, valeur cible et délai, puis un « De façon à… » qui précise le bénéfice fonctionnel visé.","s":1},{"q":"Quelle triade caractérise le syndrome de Kartagener ?","o":["Sinusite paranasale chronique, bronchectasies et situs inversus","Toux, dyspnée et cyanose","Fièvre, expectoration et douleur","Emphysème, bronchite et asthme"],"r":0,"e":"Le syndrome de Kartagener associe une sinusite paranasale chronique, des bronchectasies et un situs inversus.","s":1},{"q":"À quel sous-groupe appartient le syndrome de Kartagener ?","o":["Aux mucoviscidoses","À la dyskinésie ciliaire primitive, sous-groupe d'immotilité ciliaire","Aux pneumoconioses","Aux déficits immunitaires primitifs"],"r":1,"e":"Il fait partie d'un sous-groupe d'immotilité ciliaire appelé dyskinésie ciliaire primitive : les cils de l'épithélium pulmonaire deviennent immobiles.","s":1},{"q":"Quelle conséquence a l'immobilité ciliaire dans le syndrome de Kartagener ?","o":["Une hypersécrétion isolée","Une atteinte de la clairance mucociliaire prédisposant aux infections respiratoires à répétition","Une paralysie diaphragmatique","Une fibrose pulmonaire"],"r":1,"e":"L'immobilité des cils compromet la clairance mucociliaire dans le tractus respiratoire, ce qui prédispose aux infections respiratoires à répétition.","s":1},{"q":"Quelles bronches sont concernées par les bronchectasies selon Postiaux (1999) ?","o":["Les bronches souches uniquement","Les voies sous-segmentaires, bronches cartilagineuses de moyen calibre, de la 5e à la 10e division bronchique","Les bronchioles terminales","La trachée et les bronches souches"],"r":1,"e":"Les bronchectasies touchent les voies respiratoires sous-segmentaires, bronches cartilagineuses de moyen calibre, de la 5e à la 10e division bronchique.","s":1},{"q":"Quel est le mécanisme de l'hyperinflation ?","o":["Une augmentation du calibre bronchique","La diminution du calibre bronchique conduisant à une fermeture prématurée des bronches à l'expiration, avec piégeage d'air","Une paralysie diaphragmatique","Une augmentation de la compliance thoracique"],"r":1,"e":"La diminution du calibre bronchique, cause de l'obstruction, conduit à une fermeture prématurée des bronches pendant l'expiration, induisant un piégeage d'air (air trapping).","s":1},{"q":"Quels signes d'inspection présente le patient atteint du syndrome de Kartagener ?","o":["Cyanose périphérique, doigts en baguette de tambour, ongles en verre de montre et thorax en tonneau","Œdème des membres inférieurs et turgescence jugulaire","Pâleur et sueurs","Tirage intercostal et battement des ailes du nez"],"r":0,"e":"L'inspection retrouve une cyanose périphérique, des doigts en baguette de tambour, des ongles en verre de montre et un thorax en tonneau, le patient étant eupnéique au repos.","s":1},{"q":"Quel résultat gazométrique définit l'hypoxémie chez ce patient ?","o":["pH 7,40","pCO2 43,1","pO2 51,2","HCO3 26,2"],"r":2,"e":"La gazométrie à l'air ambiant retrouve pH 7,40, pCO2 43,1, pO2 51,2 correspondant à l'hypoxémie, et HCO3 26,2.","s":1},{"q":"Que décrit le grade 2 de l'échelle de Fletcher modifiée ?","o":["Dyspnée au repos","Capable de suivre des personnes du même âge sur terrain plat, mais pas en montant un plan incliné ou une volée d'escaliers","Aucune limitation à l'effort","Dyspnée pour la toilette"],"r":1,"e":"Le grade 2 signifie que le patient est capable de suivre des personnes du même âge sur terrain plat mais ne peut le faire en montant un plan incliné ou une volée d'escaliers.","s":1},{"q":"Quel instrument évalue la force musculaire respiratoire ?","o":["Le test de marche de 6 minutes","La PIM et la PEM","La spirométrie","L'échelle de Borg"],"r":1,"e":"La force musculaire respiratoire s'évalue par la PIM (pression inspiratoire maximale) et la PEM (pression expiratoire maximale).","s":1},{"q":"Quels instruments évaluent la qualité de vie dans ce cadre ?","o":["Le SF-36 et le SRDQ","Le MRC et l'indice de dyspnée basal","Le SWT et le 6MWT","Les journaux d'activité"],"r":0,"e":"La qualité de vie s'évalue par le SF-36 et le SRDQ ; la dyspnée dans les activités par le MRC et l'indice de dyspnée basal ; le niveau d'activité quotidienne par les journaux d'activité.","s":1},{"q":"Dans le tableau physiopathologique de Kartagener, que produit l'hyperinflation ?","o":["Une augmentation du volume résiduel et une diminution globale de la mobilité thoracique bilatérale","Une augmentation de la clairance mucociliaire","Une amélioration du rapport V/Q","Une augmentation de la force musculaire"],"r":0,"e":"L'hyperinflation entraîne une augmentation du volume résiduel et une diminution globale de la mobilité thoracique bilatérale, contribuant à l'altération du rapport V/Q.","s":1},{"q":"Quelle activité/participation est altérée chez le patient atteint de Kartagener ?","o":["La lecture","La natation, qu'il a arrêtée","La conduite","Le travail"],"r":1,"e":"Le diagnostic kinésithérapique mentionne explicitement les altérations de l'Activité/Participation avec la natation, qu'il a arrêtée.","s":1},{"q":"Dans le plan d'intervention résolu, comment est opérationnalisé l'ELTGOL ?","o":["Assis, 3 fois par semaine","En décubitus latéral droit et gauche, 5 fois par semaine","Debout, quotidiennement","En décubitus dorsal, 2 fois par semaine"],"r":1,"e":"L'ELTGOL est réalisé en décubitus latéral droit et décubitus latéral gauche, 5 fois par semaine, pour les objectifs 1, 2 et 3.","s":1},{"q":"À quelle intensité est prescrit l'entraînement aérobie dans le cas résolu ?","o":["À 40-50 % ou Borg 8-9","À 60-70 % d'intensité ou Borg 12-13, 3 fois par semaine","À 85-90 % de la FC maximale","Sans repère d'intensité"],"r":1,"e":"L'entraînement aérobie sur cycloergomètre ou tapis roulant est prescrit 3 fois par semaine à 60-70 % d'intensité ou Borg 12-13.","s":1},{"q":"Quelle règle le cours énonce-t-il pour construire le plan d'intervention ?","o":["Choisir d'abord la technique que l'on maîtrise le mieux","Identifier d'abord l'objectif à atteindre (« pour quoi ? ») et seulement ensuite le nom de la technique","Suivre le protocole du service","Commencer par la fréquence des séances"],"r":1,"e":"Le cours précise qu'il faut identifier en premier l'objectif à atteindre (« pour quoi ? ») et seulement ensuite le NOM de la technique à utiliser.","s":1},{"q":"Dans l'examen subjectif cardio-respiratoire, l'histoire médicale et les habitudes sont recueillies :","o":["Avant le début et l'évolution","Après la symptomatologie actuelle, avant les altérations fonctionnelles et d'activité","En tout dernier","Uniquement si le patient est fumeur"],"r":1,"e":"L'ordre du cours : début, évolution, symptomatologie actuelle, histoire médicale et habitudes, puis altérations fonctionnelles et d'activité/participation.","s":1},{"q":"Dans l'examen objectif cardio-respiratoire, la percussion se situe :","o":["Avant l'inspection","Entre la palpation et l'auscultation pulmonaire","Après les examens complémentaires","En premier"],"r":1,"e":"La séquence complète : quantifier les symptômes majeurs, inspection, palpation, percussion, auscultation, autres tests, puis examens complémentaires.","s":1},{"q":"La spirométrie évalue, dans la grille d'instruments par composante CIF :","o":["La tolérance à l'effort","La fonction pulmonaire, au niveau structure et fonction du corps","La qualité de vie","Le niveau d'activité physique quotidienne"],"r":1,"e":"La tolérance à l'effort s'évalue par épreuve d'effort, 6MWT ou shuttle walking test ; la dyspnée par les échelles de Borg.","s":1},{"q":"La PIM et la PEM mesurent :","o":["La capacité fonctionnelle","La force musculaire respiratoire","La qualité de vie","Le volume résiduel"],"r":1,"e":"Pressions inspiratoire et expiratoire maximales. La force musculaire périphérique s'évalue par test fonctionnel, dynamométrie ou test de répétition maximale.","s":1},{"q":"Les journaux d'activité servent à évaluer :","o":["La capacité fonctionnelle","Le niveau d'activité physique quotidienne","La dyspnée dans les activités","La force musculaire"],"r":1,"e":"La dyspnée dans les activités s'évalue par le MRC ou l'indice de dyspnée basal ; la qualité de vie par le SF-36 ou le SRDQ.","s":1},{"q":"Le SF-36 et le SRDQ sont des instruments d'évaluation :","o":["De la fonction pulmonaire","De la qualité de vie","De la force musculaire","De la tolérance à l'effort"],"r":1,"e":"Ils se situent au niveau activité et participation de la CIF, là où se posent les objectifs les plus significatifs pour le patient.","s":1},{"q":"Dans le cas de la patiente opérée d'une gastrectomie, la pneumonie a été favorisée par :","o":["Le tabagisme","La dépression du système immunitaire par la chimiothérapie","L'âge avancé","Une allergie"],"r":1,"e":"Elle avait reçu deux cycles de chimiothérapie pour une néoplasie gastrique, et ne présentait ni habitudes tabagiques ni alcooliques.","s":1},{"q":"Chez cette patiente, la radiographie thoracique montre :","o":["Un pneumothorax","Une condensation à la base du poumon gauche et une rétraction des deux hémi-coupoles diaphragmatiques","Un épanchement pleural droit","Un thorax normal"],"r":1,"e":"L'auscultation retrouve une diminution des bruits respiratoires aux bases, plus marquée à gauche, et des râles de haute fréquence à gauche.","s":1},{"q":"La mobilité thoracique costale inférieure gauche mesurée chez cette patiente est de :","o":["3 cm","5 cm","7,5 cm","10 cm"],"r":0,"e":"L'objectif fixé est de la normaliser à 7,5 cm en quatre à six semaines, afin d'améliorer la ventilation à la base gauche.","s":1},{"q":"Le 6MWT de cette patiente s'établit à :","o":["250 m","330 m","410 m","500 m"],"r":1,"e":"La référence féminine chez l'individu sain est de 500 m. L'écart chiffre directement la perte de capacité fonctionnelle.","s":1},{"q":"La force musculaire globale de cette patiente est cotée :","o":["2 aux quatre membres","3+ aux membres supérieurs et inférieurs","4+ aux quatre membres","5 aux quatre membres"],"r":1,"e":"L'objectif est de passer de 3+ à 4+ en quatre semaines, afin d'inverser les effets de l'inactivité et d'augmenter l'extraction d'oxygène par le muscle.","s":1},{"q":"Dans le tableau physiopathologique de ce cas, la diminution de la mobilité diaphragmatique bilatérale et costale inférieure gauche conduit à :","o":["Une rétention de sécrétions","Une augmentation du travail respiratoire","Une hypoxémie isolée","Une perte de poids"],"r":1,"e":"La chaîne converge ensuite, avec la baisse de force liée à l'alitement, vers la diminution de la tolérance à l'effort.","s":1},{"q":"Le premier problème réel hiérarchisé chez cette patiente est :","o":["La diminution de la force musculaire globale","L'augmentation de la résistance des voies aériennes périphériques","La diminution de la tolérance à l'effort","La diminution de la mobilité diaphragmatique"],"r":1,"e":"Il est dû à la rétention de sécrétions périphériques, par atteinte immunitaire et diminution de l'efficacité de la toux, qui compromet l'épuration pulmonaire.","s":1},{"q":"La diminution de la mobilité diaphragmatique bilatérale est attribuée dans ce cas :","o":["À la condensation parenchymateuse","À la cicatrice de laparotomie médiane, qui conditionne l'efficacité mécanique du diaphragme","À la perte de poids","Au déconditionnement"],"r":1,"e":"La diminution de la mobilité costale inférieure gauche est, elle, rapportée à la condensation parenchymateuse de la base gauche.","s":1},{"q":"La diminution de la force musculaire globale de cette patiente est rapportée à :","o":["La perte volémique, l'inactivité et la perte pondérale","Une atteinte neurologique","Une carence vitaminique","L'anesthésie"],"r":0,"e":"Ces trois facteurs se cumulent chez une patiente de 48 kg pour 1,59 m, dénutrie et alitée après une chirurgie lourde.","s":1},{"q":"Le premier objectif fixé chez cette patiente a pour critère :","o":["Une distance au 6MWT","L'absence de bruits adventices à l'auscultation, avec un délai immédiat","Une valeur de force musculaire","Un grade de dyspnée"],"r":1,"e":"Il vise la mobilisation et l'élimination des sécrétions, de façon à améliorer la ventilation à la base gauche. C'est l'objectif le plus urgent de la série.","s":1},{"q":"L'objectif de tolérance à l'effort chez cette patiente est fixé à :","o":["2 semaines","4 semaines","6 semaines","8 semaines"],"r":3,"e":"Il vise à réduire la dyspnée liée à l'activité, du grade 5 au grade 4 de l'échelle de Cotes, en augmentant la capacité fonctionnelle mesurée au 6MWT.","s":1},{"q":"Sans la partie « de façon à », un objectif n'est selon le cours :","o":["Qu'une mesure, non reliée à la participation","Pas mesurable","Pas atteignable","Pas temporisé"],"r":0,"e":"C'est cette seconde partie qui rattache la valeur cible à un bénéfice fonctionnel, et donc au niveau activité et participation de la CIF.","s":1},{"q":"Dans le syndrome de Kartagener, les cils de l'épithélium pulmonaire :","o":["Battent trop rapidement","Deviennent immobiles, compromettant la clairance mucociliaire","Sont absents dès la naissance","Sont remplacés par un épithélium glandulaire"],"r":1,"e":"Cette immotilité ciliaire — dyskinésie ciliaire primitive — prédispose aux infections respiratoires à répétition, d'où l'histoire clinique typique de ces patients.","s":1},{"q":"Selon Postiaux (1999), les bronchectasies s'accompagnent :","o":["D'une simple dilatation réversible","D'une destruction inflammatoire des tissus bronchiques et péribronchiques, avec accumulation de matériaux de suppuration et d'exsudat","D'une fibrose interstitielle","D'un épaississement pleural"],"r":1,"e":"La dilatation est anormale et permanente, et concerne les bronches cartilagineuses de moyen calibre, de la 5ᵉ à la 10ᵉ division bronchique.","s":1},{"q":"Comment le cours définit-il le raisonnement clinique ?","o":["Un processus purement cognitif","Un processus cognitif, affectif et psychomoteur complexe conduisant à des interprétations significatives des problèmes du patient","Une succession de tests orthopédiques","L'application d'un protocole validé"],"r":1,"e":"Le raisonnement clinique est un processus cognitif, affectif et psychomoteur complexe, qui conduit à des interprétations significatives des problèmes du patient ; il peut être compris comme une décision, un processus ou un résultat.","s":2},{"q":"Quel bénéfice professionnel le raisonnement clinique soutient-il ?","o":["L'autonomie professionnelle","La rapidité de facturation","La réduction du nombre de séances","La standardisation totale des pratiques"],"r":0,"e":"Le raisonnement clinique soutient l'autonomie professionnelle, améliore les résultats centrés sur la personne et la qualité des décisions dans les situations complexes.","s":2},{"q":"Quelles sont les trois façons d'organiser le raisonnement clinique ?","o":["Par durée, par profession et par objectif","Par âge, par pathologie et par service","Par coût, par durée et par lieu","Par subjectif, objectif et évaluation"],"r":0,"e":"On peut l'organiser par durée (automatique vs délibérée), par profession (objectifs et langage distincts) et par objectif (une stratégie pour chaque problème clinique).","s":2},{"q":"Qu'est-ce qui caractérise le Système 1 selon Kahneman ?","o":["Lent, analytique et hypothético-déductif","Rapide, intuitif, par reconnaissance de schémas","Exclusivement réservé aux débutants","Basé sur les guidelines"],"r":1,"e":"Le Système 1 est rapide, intuitif et fondé sur la reconnaissance de schémas ; le Système 2 est lent, analytique, hypothético-déductif et demande plus d'effort cognitif.","s":2},{"q":"Que fait un clinicien compétent selon le cours ?","o":["Il n'utilise que le Système 2","Il n'utilise que le Système 1","Il alterne entre les deux systèmes","Il choisit un système une fois pour toutes"],"r":2,"e":"Le cours conclut qu'un clinicien compétent alterne entre les deux systèmes.","s":2},{"q":"Quel risque court le kinésithérapeute moins expérimenté ?","o":["Il recourt au Système 2 par excès de prudence","Il recourt au Système 1 dans des situations simples et avec peu de temps : plus de risque et pratique non réfléchie","Il ne pose jamais de diagnostic","Il applique toujours les guidelines"],"r":1,"e":"Les moins expérimentés devraient recourir au Système 2, mais en pratique, dans les situations simples et avec peu de temps, ils recourent au Système 1 : plus de risque, pratique non réfléchie.","s":2},{"q":"Que garantit par défaut le Système 2 ?","o":["Une analyse complète du patient, un diagnostic plus précis et l'intégration des directives cliniques et de la pratique informée par les preuves","Une consultation plus rapide","Un moindre coût","Une meilleure adhésion du patient"],"r":0,"e":"Le Système 2 garantit une analyse complète, un diagnostic plus précis, une préparation aux informations inattendues et l'intégration des directives cliniques et de la pratique informée par les preuves.","s":2},{"q":"Quelle est la différence d'objet entre le raisonnement du médecin et celui du kinésithérapeute ?","o":["Le médecin diagnostique la pathologie, le kinésithérapeute diagnostique l'incapacité fonctionnelle, les limitations d'activité et les restrictions de participation","Il n'y a aucune différence","Le kinésithérapeute diagnostique la maladie","Le médecin utilise la CIF, pas le kinésithérapeute"],"r":0,"e":"Le médecin pose un diagnostic de pathologie, maladie ou état de santé ; le kinésithérapeute pose un diagnostic en kinésithérapie : incapacité fonctionnelle, limitations d'activité et restrictions de participation, dans le cadre de la CIF.","s":2},{"q":"Lequel de ces éléments N'EST PAS un objectif clinique nécessitant un raisonnement clinique ?","o":["Évaluer le patient","Établir un pronostic","Établir un partenariat / alliance thérapeutique","Établir la facturation de l'acte"],"r":3,"e":"Les cinq objectifs sont : évaluation du patient, pronostic, élaboration du plan et nécessité d'orienter, sélection des interventions et évaluation des progrès, établissement d'une alliance thérapeutique.","s":2},{"q":"Quelles stratégies dominent lors de l'ÉVALUATION ?","o":["Le raisonnement hypothético-déductif et le raisonnement narratif","Le raisonnement scientifique et intuitif","Le raisonnement prédictif et collaboratif","Le raisonnement interactif seul"],"r":0,"e":"À l'évaluation, le kinésithérapeute utilise le raisonnement hypothético-déductif (générer et tester des hypothèses) et le raisonnement narratif (comprendre l'expérience, les croyances et la signification) ; les deux peuvent coexister.","s":2},{"q":"En quoi consiste le raisonnement prédictif/conditionnel ?","o":["À intégrer les preuves au contexte","À envisager des scénarios « si/alors » afin d'identifier les objectifs et les priorités","À comprendre l'expérience du patient","À créer un rapport de confiance"],"r":1,"e":"Le raisonnement prédictif/conditionnel envisage des scénarios « si/alors » afin d'identifier les objectifs et les priorités ; il s'utilise à la planification des soins.","s":2},{"q":"À quoi sert le raisonnement scientifique ?","o":["À intégrer les preuves cliniques au contexte actuel du patient, en adoptant, adaptant ou contextualisant les meilleures recommandations","À négocier les objectifs","À créer l'alliance thérapeutique","À tester des hypothèses diagnostiques"],"r":0,"e":"Le raisonnement scientifique intègre les preuves cliniques au contexte du patient, en adoptant, adaptant ou contextualisant les meilleures recommandations issues des revues systématiques et des directives pratiques.","s":2},{"q":"Quelles stratégies sont dominantes pour créer une alliance thérapeutique ?","o":["Le raisonnement interactif et le raisonnement collaboratif","Le raisonnement scientifique et intuitif","Le raisonnement hypothético-déductif","Le raisonnement diagnostique"],"r":0,"e":"Le raisonnement interactif renforce la relation thérapeutique et le raisonnement collaboratif facilite le consensus et la résolution partagée des problèmes.","s":2},{"q":"Qu'est-ce qui est associé à de meilleurs résultats selon le cours ?","o":["Une durée de séance plus longue","Une meilleure alliance thérapeutique","Un plus grand nombre de tests","Un protocole standardisé"],"r":1,"e":"Le cours indique qu'une meilleure alliance est associée à de meilleurs résultats, et qu'une alliance collaborative garantit davantage de succès et de satisfaction.","s":2},{"q":"Quelle stratégie domine pour la résolution de problèmes pratiques en contexte de temps limité ?","o":["Le raisonnement scientifique","Le raisonnement intuitif","Le raisonnement narratif","Le raisonnement collaboratif"],"r":1,"e":"Le raisonnement intuitif domine pour la résolution de problèmes pratiques, en contexte de temps limité ou en présence de risques d'intervention.","s":2},{"q":"Quels sont les trois cercles au croisement desquels s'inscrit le modèle d'évaluation et d'intervention ?","o":["Meilleures preuves scientifiques, expertise clinique et attentes du patient","Coût, durée et efficacité","Structure, fonction et activité","Diagnostic, pronostic et traitement"],"r":0,"e":"Le modèle s'inscrit au croisement des meilleures preuves scientifiques, de l'expertise clinique / informations cliniques et des attentes du patient : c'est l'espace de la PIE.","s":2},{"q":"Quels sont les cinq verbes de la séquence d'évaluation ?","o":["Écouter, observer, palper, tester, enregistrer","Lire, écrire, mesurer, comparer, conclure","Voir, toucher, sentir, entendre, goûter","Examiner, diagnostiquer, traiter, évaluer, sortir"],"r":0,"e":"La séquence d'évaluation s'organise autour de : écouter (entretien), observer, palper, tester et enregistrer.","s":2},{"q":"Que signifie le SIN de l'examen subjectif ?","o":["Signes, Investigations, Notes","Sévérité et irritabilité des symptômes","Subjectif, Interrogatoire, Neurologique","Symptômes, Intensité, Nature"],"r":1,"e":"Le SIN désigne la gravité (sévérité) et l'irritabilité des symptômes.","s":2},{"q":"Que cherche-t-on à déterminer avec le « comportement des symptômes » ?","o":["Ce qui améliore ou aggrave la situation : positions, mouvements, moment de la journée","La localisation exacte de la douleur","L'intensité au repos","La durée d'évolution"],"r":0,"e":"Le comportement des symptômes précise ce qui améliore ou aggrave la situation : positions, mouvements, moment de la journée.","s":2},{"q":"Quelles sont les quatre questions à se poser pour planifier l'examen objectif ?","o":["Quel type de douleur ? Quelles structures et fonctions ? Quels tests ? Dans quel ordre ?","Combien de séances ? À quel prix ? Avec qui ? Où ?","Quel diagnostic médical ? Quel traitement ? Quel pronostic ? Quelle sortie ?","Quel âge ? Quelle profession ? Quel sport ? Quelle motivation ?"],"r":0,"e":"Planifier l'examen objectif consiste à définir les hypothèses à tester : quel type de douleur, quelles structures et fonctions à l'origine des symptômes, quels tests à effectuer et dans quel ordre.","s":2},{"q":"Quel est le rôle de l'examen objectif ?","o":["Recueillir les antécédents","Confirmer ou infirmer les principales hypothèses générées après l'examen subjectif, selon une logique mesurable","Négocier les objectifs","Établir le pronostic"],"r":1,"e":"L'examen objectif confirme ou infirme les principales hypothèses générées après l'examen subjectif, et il suit une logique mesurable.","s":2},{"q":"Quel test spécial est cité pour l'épaule ?","o":["Le test de Lachman","Le test de Neer","Le test de Phalen","Le signe de Tinel"],"r":1,"e":"Le test de Neer est cité pour l'épaule et le test de Lachman pour le genou.","s":2},{"q":"Que comprend l'examen neurologique dans cette séquence ?","o":["Réflexes myotendineux, sensibilité tactile, vibratoire et douloureuse, dermatomes et myotomes","Amplitude active et passive","Palpation des points gâchettes","Échelles de fonctionnalité"],"r":0,"e":"L'examen neurologique comprend les réflexes myotendineux, la sensibilité tactile, vibratoire et douloureuse, ainsi que les dermatomes et myotomes.","s":2},{"q":"Que doit établir, dans la mesure du possible, la description d'un problème principal ?","o":["Un lien de causalité","Le diagnostic médical","Le coût du traitement","La durée de la prise en charge"],"r":0,"e":"Dans la mesure du possible, la description du problème primaire doit établir un lien de causalité : « limitation de l'amplitude… DUE À une rétraction myofasciale et capsulo-ligamentaire ».","s":2},{"q":"Pourquoi identifier les problèmes POTENTIELS ?","o":["Pour justifier davantage de séances","Afin de les prévenir et d'éviter qu'ils ne deviennent des problèmes réels","Pour compléter le dossier administratif","Pour informer le médecin"],"r":1,"e":"Les problèmes potentiels doivent être identifiés afin d'être prévenus et d'éviter qu'ils ne deviennent des problèmes réels.","s":2},{"q":"Sur quoi se base le diagnostic en kinésithérapie ?","o":["Sur la pathologie médicale","Sur les limitations fonctionnelles et la symptomatologie, et non sur la pathologie","Sur les résultats d'imagerie","Sur l'âge et les comorbidités"],"r":1,"e":"Le diagnostic en kinésithérapie est une classification qui catégorise l'état clinique sous l'angle de la kinésithérapie ; il se base sur les limitations fonctionnelles et la symptomatologie, et non sur la pathologie.","s":2},{"q":"Sur quoi les objectifs doivent-ils toujours être basés ?","o":["Sur les problèmes identifiés","Sur les préférences du kinésithérapeute","Sur la durée de prise en charge autorisée","Sur les guidelines uniquement"],"r":0,"e":"Les objectifs doivent toujours être basés sur les problèmes identifiés, être SMART, utiliser des verbes et être hiérarchisés en fonction des problèmes.","s":2},{"q":"Comment le cours définit-il le pronostic ?","o":["La prévision de l'évolution clinique et fonctionnelle d'un patient après son évaluation","Le diagnostic différentiel","La liste des techniques à utiliser","Le résultat du dernier bilan"],"r":0,"e":"Le pronostic est la prévision de l'évolution clinique et fonctionnelle d'un patient après son évaluation ; il repose sur les données cliniques, les preuves, l'expérience et les caractéristiques individuelles, et tient compte des attentes du patient.","s":2},{"q":"À quoi sert le pronostic ?","o":["À définir des objectifs réalistes, orienter le plan d'intervention et gérer les attentes du patient et de l'équipe","À justifier une prolongation de traitement","À classer le patient par gravité","À choisir le service d'accueil"],"r":0,"e":"Le pronostic permet de définir des objectifs réalistes, d'orienter le plan d'intervention et de gérer les attentes du patient et de l'équipe soignante.","s":2},{"q":"Quelle base de données propose des résumés de preuves spécifiques aux interventions en kinésithérapie ?","o":["PEDro","PubMed","NICE","Kennisplatform"],"r":0,"e":"PEDro propose des résumés des preuves pour les interventions en kinésithérapie ; la Cochrane Library donne les revues systématiques, Kennisplatform et NICE des directives cliniques.","s":2},{"q":"Selon le cours, le raisonnement clinique peut être compris comme :","o":["Uniquement un processus","Une décision, un processus ou un résultat","Uniquement un résultat","Une compétence innée"],"r":1,"e":"Ces trois lectures sont complémentaires : elles correspondent au moment où l'on tranche, à la démarche qui y conduit, et à l'interprétation qui en sort.","s":2},{"q":"Le raisonnement clinique est qualifié de processus :","o":["Purement cognitif","Cognitif, affectif et psychomoteur","Uniquement analytique","Exclusivement intuitif"],"r":1,"e":"Le cours insiste : ce n'est pas seulement un processus cognitif. Les apports psychomoteurs du patient ne suffisent pas, il faut intégrer ses attentes et sa perspective.","s":2},{"q":"Les cinq verbes de la séquence d'évaluation sont :","o":["Écouter, observer, palper, tester, enregistrer","Interroger, examiner, diagnostiquer, traiter, réévaluer","Voir, toucher, mesurer, noter, conclure","Recueillir, analyser, décider, agir, contrôler"],"r":0,"e":"L'écoute correspond à l'entretien ; observation, palpation et tests relèvent de l'examen objectif ; l'enregistrement conditionne le suivi et la réévaluation.","s":2},{"q":"Le raisonnement narratif, mobilisé lors de l'évaluation, vise à :","o":["Générer et tester des hypothèses","Comprendre l'expérience, les croyances et la signification pour le patient","Envisager des scénarios si/alors","Intégrer les preuves scientifiques"],"r":1,"e":"Il coexiste avec le raisonnement hypothético-déductif, et le cours précise que les deux peuvent intervenir au cours d'une même consultation.","s":2},{"q":"Le raisonnement collaboratif, en phase de planification, comprend :","o":["Le pronostic, les objectifs, les priorités et la nécessité d'une orientation","Uniquement le choix des exercices","La seule lecture des recommandations","L'analyse statistique des résultats"],"r":0,"e":"Les objectifs y sont négociés avec la personne et, le cas échéant, avec l'équipe. C'est ce qui donne sens au « Agreed Upon » des objectifs SMART.","s":2},{"q":"Le raisonnement scientifique consiste à :","o":["Suivre un protocole sans adaptation","Intégrer les preuves cliniques au contexte du patient en adoptant, adaptant ou contextualisant les meilleures recommandations","Se fier à l'expérience seule","Mesurer les progrès"],"r":1,"e":"Il s'appuie sur les revues systématiques et les directives pratiques. Le raisonnement intuitif poursuit le même but, mais par un jugement implicite.","s":2},{"q":"Le raisonnement interactif contribue à l'alliance thérapeutique en :","o":["Facilitant le consensus","Renforçant la relation : confiance, justification des interventions et du plan, création d'un rapport","Testant des hypothèses","Sélectionnant les interventions"],"r":1,"e":"Le raisonnement collaboratif, lui, facilite le consensus par la résolution partagée des problèmes et des décisions prises en équipe patient-professionnel.","s":2},{"q":"Selon le tableau de synthèse, catégoriser les patients pour les interventions mobilise :","o":["Le raisonnement diagnostique, hypothético-déductif et narratif","Le raisonnement prédictif et collaboratif","Le raisonnement scientifique","Le raisonnement intuitif"],"r":0,"e":"Établir un pronostic mobilise le prédictif, le conditionnel et le collaboratif ; sélectionner les interventions relève du scientifique ; l'urgence appelle l'intuitif.","s":2},{"q":"Le cours précise que le professionnel lui-même :","o":["N'a aucune influence sur le processus","Influence le processus et la prise de décision","Doit rester strictement neutre","Suit un algorithme fixe"],"r":1,"e":"C'est pourquoi les stratégies se recoupent en pratique et pourquoi le choix de l'une ou de l'autre dépend de la question clinique posée.","s":2},{"q":"Le modèle d'évaluation et d'intervention s'inscrit au croisement de trois cercles :","o":["Meilleures preuves scientifiques, expertise clinique et attentes du patient","Diagnostic, traitement et pronostic","Patient, famille et équipe","Structure, fonction et participation"],"r":0,"e":"Cet espace d'intersection est celui de la pratique informée par l'évidence. Le modèle est adapté de Brody et Hall (1999) et du Guide de l'APTA (2001).","s":2},{"q":"La septième étape du modèle en sept étapes est :","o":["L'intervention","La réévaluation, en fonction des résultats","Le diagnostic","Le pronostic"],"r":1,"e":"Elle referme la boucle : examen, évaluation, problèmes, diagnostic, résultats, intervention, réévaluation. Sans elle, le modèle serait linéaire et non itératif.","s":2},{"q":"Parmi les rubriques de l'examen subjectif, les antécédents des symptômes cherchent à établir :","o":["Ce qui améliore ou aggrave","Comment cela a commencé — traumatisme, début insidieux, effort répétitif — et depuis quand","La sévérité et l'irritabilité","Les attentes du patient"],"r":1,"e":"Le comportement des symptômes concerne ce qui améliore ou aggrave ; le SIN, la sévérité et l'irritabilité ; ce sont trois rubriques distinctes.","s":2},{"q":"Dans l'examen subjectif, la rubrique « données personnelles » comprend notamment :","o":["Le nom, l'âge, la profession, l'état civil et les coordonnées","Les résultats d'imagerie","Les médicaments habituels","Les objectifs du patient"],"r":0,"e":"La profession y figure explicitement : elle est souvent déterminante pour comprendre l'origine des symptômes et pour formuler des objectifs de participation.","s":2},{"q":"Les antécédents personnels et familiaux recueillis comprennent :","o":["Les seules chirurgies","Chirurgies, pathologies chroniques, systémiques, auto-immunes et médicaments habituels","Les seuls antécédents familiaux","Les habitudes sportives uniquement"],"r":1,"e":"Cette rubrique conditionne la sécurité de l'intervention et peut révéler des drapeaux rouges justifiant une orientation vers un autre professionnel.","s":2},{"q":"Dans l'examen objectif, la palpation explore :","o":["La posture statique et dynamique","La température de la peau, le tonus et la raideur musculaires, les points gâchettes et les zones symptomatiques","Les réflexes myotendineux","Les amplitudes articulaires"],"r":1,"e":"L'observation porte sur la posture, l'œdème, l'atrophie, les cicatrices, les déformations et la marche — ce sont deux composantes distinctes de l'examen.","s":2},{"q":"L'évaluation de la force musculaire dans l'examen objectif se fait :","o":["Par observation seule","Par évaluation manuelle selon le MRC ou par dynamométrie","Par palpation","Par imagerie"],"r":1,"e":"Le MRC — Medical Research Council — est l'échelle de cotation manuelle de référence. La dynamométrie apporte une mesure chiffrée et reproductible.","s":2},{"q":"L'examen neurologique, dans cette séquence, comprend :","o":["Les réflexes myotendineux, la sensibilité tactile, vibratoire et douloureuse, les dermatomes et les myotomes","Uniquement les réflexes","Uniquement la force musculaire","Les tests orthopédiques"],"r":0,"e":"Dermatomes et myotomes permettent de localiser le niveau d'une atteinte radiculaire, ce que ne permet pas un simple testing global.","s":2},{"q":"Le test de Lachman est cité dans le cours comme test spécial :","o":["De l'épaule","Du genou","De la hanche","Du poignet"],"r":1,"e":"Le test de Neer est celui cité pour l'épaule. Les tests spéciaux visent une articulation ou une structure précise et servent à confirmer ou infirmer une hypothèse.","s":2},{"q":"L'examen fonctionnel évalue :","o":["Les amplitudes passives","Les activités spécifiques que le patient ne peut pas réaliser — s'accroupir, monter des escaliers, s'asseoir — et mobilise des échelles de fonctionnalité","La force isométrique","La sensibilité"],"r":1,"e":"Il fait le lien entre les déficiences mesurées et le niveau activité de la CIF, où se posent l'essentiel des objectifs SMART.","s":2},{"q":"L'étape de réflexion consiste notamment à :","o":["Choisir les exercices","Interpréter et organiser les données, inscrire les résultats dans le cadre de la CIF et construire un tableau physiopathologique","Mesurer les amplitudes","Rédiger le compte rendu"],"r":1,"e":"Le tableau physiopathologique enchaîne les mécanismes : de la lésion initiale aux conséquences fonctionnelles, sociales et émotionnelles.","s":2},{"q":"Quel est le profil sportif de Sara ?","o":["Sprinteuse en dos crawlé depuis 2 ans","Athlète de longue distance en nage libre et papillon, en compétition depuis l'âge de 12 ans","Joueuse de handball","Gymnaste de haut niveau"],"r":1,"e":"Sara nage depuis l'âge de 8 ans et est en compétition depuis 12 ans ; elle est athlète de longue distance en nage libre et papillon.","s":3},{"q":"Quelle est l'intensité de la douleur rapportée à l'examen subjectif ?","o":["Constante à 8/10","Intermittente, variant de 3/10 à 6/10 END","Absente au repos et à l'effort","Permanente à 2/10"],"r":1,"e":"La douleur est bilatérale, intermittente, variant de 3/10 à 6/10 sur l'échelle numérique de la douleur.","s":3},{"q":"Combien de temps la sensation douloureuse persiste-t-elle après l'entraînement ?","o":["Quelques minutes","3 à 4 heures puis plus rien","Elle diminue pendant 3 à 4 heures, puis une sensation persiste 2 jours","Une semaine"],"r":2,"e":"À la fin de la séance ou de la compétition, la douleur persiste mais diminue pendant 3 à 4 heures ; ensuite une sensation de douleur persiste dans la zone pendant 2 jours.","s":3},{"q":"Dans quelle nage et quelle phase la douleur est-elle maximale ?","o":["En papillon, phase intermédiaire de traction et phase de récupération aérienne","En brasse, phase de poussée","En dos, phase d'entrée de main","En nage libre uniquement"],"r":0,"e":"La douleur est plus forte en papillon, en particulier pendant la phase intermédiaire de traction et la phase de récupération (aérienne).","s":3},{"q":"Quels signes négatifs sont importants dans ce cas ?","o":["L'absence de symptômes nocturnes et l'absence de raideur ou de douleur matinale","L'absence de douleur à l'effort","L'absence d'antécédent traumatique","L'absence de douleur bilatérale"],"r":0,"e":"Il n'y a pas de symptômes nocturnes, ni de raideur ou de douleur matinale, ce qui oriente contre une composante inflammatoire dominante ou rhumatismale.","s":3},{"q":"Quel a été l'épisode initial déclenchant ?","o":["Une chute en compétition","Une forte douleur de l'épaule droite en soulevant une valise lourde, avec apparition secondaire à gauche sans raison apparente","Un changement d'entraîneur","Une luxation en entraînement"],"r":1,"e":"Au début de la compétition, une forte douleur de l'épaule droite est apparue en zone acromiale supérieure et antérieure en soulevant une valise lourde ; après la reprise, la même douleur est apparue à gauche sans raison apparente.","s":3},{"q":"Que montrent les examens complémentaires ?","o":["Une rupture de la coiffe des rotateurs","Une instabilité structurelle","Ils sont tous négatifs : scanner cervical, échographie et IRM de l'épaule","Une lésion du labrum"],"r":2,"e":"Le scanner cervical, l'échographie des parties molles de l'épaule et l'IRM de l'épaule sont tous négatifs.","s":3},{"q":"Quelle conclusion tire-t-on des examens d'imagerie négatifs ?","o":["Il n'y a pas de problème réel","Les sources sont probablement tissulaires fonctionnelles et non structurelles","Il faut refaire les examens","La douleur est purement psychogène"],"r":1,"e":"Les examens d'imagerie étant négatifs, les sources sont probablement tissulaires fonctionnelles et non structurelles.","s":3},{"q":"Quel est le mécanisme de douleur dominant retenu ?","o":["Neuropathique","Nociplastique pur","Nociceptif, à profil +++ mécanique / + inflammatoire","Psychogène"],"r":2,"e":"L'hypothèse retenue est une douleur nociceptive à l'épaule, sur un modèle +++ mécanique et + inflammatoire.","s":3},{"q":"Quelle amplitude de flexion gléno-humérale a été mesurée ?","o":["120°","140°","170°","190°, signant une hypermobilité"],"r":3,"e":"La flexion est à 190° et l'abduction à 140° : hypermobilité, avec rotation supérieure excessive de l'omoplate et bord interne proéminent.","s":3},{"q":"Quelle anomalie est retrouvée dans TOUS les mouvements physiologiques actifs ?","o":["Une douleur en fin de course","Un mouvement excessif de l'omoplate avec accentuation marquée du bord interne","Une limitation de l'amplitude","Un craquement articulaire"],"r":1,"e":"Dans tous les mouvements physiologiques actifs évalués, il y avait un mouvement excessif de l'omoplate, avec une accentuation marquée du bord interne.","s":3},{"q":"Que montre le test isométrique des rotateurs à 90° ?","o":["Une douleur vive en rotation interne","Pas de douleur, mais une force nettement réduite en rotation externe","Une force normale dans les deux sens","Une impossibilité totale de contraction"],"r":1,"e":"Le test isométrique des rotateurs externes et internes à 90° est sans douleur, mais la force est nettement réduite en rotation externe.","s":3},{"q":"Que concluent les tests de Speed et Biceps Load II négatifs ?","o":["Qu'il faut refaire l'IRM","Que la longue portion du biceps est écartée comme source des symptômes","Qu'il y a une rupture complète du biceps","Que l'épaule est stable"],"r":1,"e":"Les tests de Speed / « Palm up » et Biceps Load II sont négatifs, ce qui écarte la longue portion du biceps comme source des symptômes.","s":3},{"q":"Quelle est la sensation de fin de course aux amplitudes passives de l'épaule ?","o":["Dure et osseuse","Lâche dans toutes les directions, avec hypermobilité pire à droite","Ferme et capsulaire","Douloureuse et défensive"],"r":1,"e":"L'évaluation des amplitudes passives montre une hypermobilité dans toutes les directions, pire à droite, sans douleur, avec un end-feel lâche dans toutes les directions.","s":3},{"q":"Comment se comporte le quadrant inférieur au test différentiel ?","o":["Amélioration avec compression et aggravation avec distraction","Aggravation avec compression et amélioration avec distraction","Aucun changement avec l'une ou l'autre","Il est négatif"],"r":0,"e":"Le quadrant inférieur est positif bilatéralement et reproduit les symptômes ; le différentiel montre une amélioration avec la compression et une aggravation avec la distraction.","s":3},{"q":"Quels tests d'instabilité sont positifs ?","o":["Le test d'appréhension (Crank) antérieur et le test push-pull postérieur","Le test de Neer et le test de Hawkins","Le test de Jobe seul","Aucun test d'instabilité"],"r":0,"e":"Le test d'appréhension (Crank) est positif en antérieur et reproduit les symptômes ; le test push-pull est positif en postérieur avec un léger inconfort.","s":3},{"q":"Où la palpation retrouve-t-elle des points sensibles ?","o":["Dans le deltoïde antérieur","Dans le ventre de l'infra-épineux et du petit rond","Dans le grand pectoral","Dans le trapèze supérieur"],"r":1,"e":"La palpation retrouve des points sensibles et une augmentation de la sensibilité dans le ventre du muscle infra-épineux et du petit rond.","s":3},{"q":"Quelle posture typique est observée chez cette nageuse ?","o":["Une rétroversion des épaules","Une légère rotation interne et antéversion des épaules, avec cyphose dorsale et lordose lombaire accrues","Un rachis rectiligne","Une scoliose structurale"],"r":1,"e":"L'observation retrouve une légère rotation interne et antéversion des épaules, typique chez les nageurs, avec cyphose dorsale et lordose lombaire accrues.","s":3},{"q":"Quelle composante CIF correspond à « incapacité à réaliser l'intégralité des entraînements avec une charge plus élevée » ?","o":["Fonctions du corps","Activités","Participation","Facteurs environnementaux"],"r":1,"e":"La limitation lors de la natation et l'incapacité à réaliser l'intégralité des entraînements relèvent des Activités ; la limitation de ses performances d'athlète de haut niveau relève de la Participation.","s":3},{"q":"Quel facteur environnemental est identifié dans ce cas ?","o":["Le soutien familial","Les exigences élevées, l'environnement compétitif et le peu de repos","L'absence de matériel","La distance au lieu d'entraînement"],"r":1,"e":"Le facteur environnemental identifié est l'environnement compétitif avec des exigences élevées et peu de repos.","s":3},{"q":"Comment est formulé le problème principal ?","o":["Tendinopathie de la coiffe des rotateurs bilatérale","Douleur intermittente 3/10 à 7/10 END dans les épaules, probablement d'origine capsulaire, due à une hypermobilité articulaire et un mauvais contrôle moteur","Conflit sous-acromial structural","Instabilité post-traumatique droite"],"r":1,"e":"Le problème principal est formulé avec son lien de causalité : douleur intermittente (3/10 à 7/10 END) dans les épaules, probablement d'origine capsulaire, due à une hypermobilité articulaire et à un mauvais contrôle moteur.","s":3},{"q":"Quel est le premier problème POTENTIEL identifié ?","o":["Une luxation récidivante","Le risque de détérioration de l'état psychologique, en raison de la durée des symptômes et de la crainte de ne pas retrouver son niveau","Une raideur articulaire","Une amyotrophie sévère"],"r":1,"e":"Le premier problème potentiel est le risque de détérioration de l'état psychologique, en raison de la durée des symptômes et de la crainte de ne pas retrouver le niveau antérieur.","s":3},{"q":"Comment est rédigé le diagnostic en kinésithérapie de ce cas ?","o":["Par la pathologie : conflit sous-acromial bilatéral","Par la limitation d'activité et de participation, en raison d'une douleur probablement capsulaire, provoquée par une hypermobilité et un mauvais contrôle moteur scapulaire et gléno-huméral","Par le résultat de l'IRM","Par le score d'une échelle fonctionnelle"],"r":1,"e":"Le diagnostic porte sur la limitation dans la pratique de la natation et la limitation de participation en tant qu'athlète de haut niveau, en raison d'une douleur d'épaule probablement capsulaire, provoquée par une hypermobilité et un mauvais contrôle moteur.","s":3},{"q":"Quel est le délai de retour au niveau antérieur annoncé dans le pronostic ?","o":["2 à 4 semaines","3 à 6 mois","1 an","Plus de 2 ans"],"r":1,"e":"Le pronostic est favorable, avec un retour au niveau de performance antérieur prévu à moyen terme, dans 3 à 6 mois.","s":3},{"q":"Quel comportement perpétue l'inflammation de la capsule ?","o":["Le repos complet","L'insistance à s'entraîner avec une douleur supérieure à 3/10","L'étirement quotidien","La natation en dos"],"r":1,"e":"Le pronostic dépend notamment de l'insistance à s'entraîner avec une douleur supérieure à 3/10, ce qui perpétue l'inflammation de la capsule.","s":3},{"q":"Que contient la phase 2 du rétablissement (4 à 12 semaines) ?","o":["La réduction de la douleur et le contrôle de la réactivité capsulaire","Le renforcement spécifique et l'intégration du contrôle moteur de l'omoplate","Le retour aux charges maximales","La sortie du traitement"],"r":1,"e":"Phase 1 (2-4 semaines) : réduction de la douleur et contrôle de l'inflammation capsulaire ; phase 2 (4-12 semaines) : renforcement spécifique et intégration du contrôle moteur de l'omoplate ; phase 3 (> 12 semaines) : retour progressif aux charges maximales avec surveillance.","s":3},{"q":"Quel est le premier objectif SMART défini, avec son délai ?","o":["Réduire l'intensité de la douleur à 2/10 END en 4 semaines","Améliorer le contrôle moteur scapulaire en 8 semaines","Retourner à la compétition en 12 semaines","Récupérer 190° de flexion en 2 semaines"],"r":0,"e":"Le premier objectif est de réduire l'intensité de la douleur à 2/10 END en 4 semaines, afin d'améliorer la capacité à supporter des entraînements plus exigeants et l'adhésion au plan.","s":3},{"q":"Quel est le but explicite de l'amélioration du contrôle moteur scapulaire ?","o":["Augmenter la vitesse de nage","Prévenir l'aggravation de l'état et les récidives futures","Gagner de l'amplitude","Réduire la cyphose dorsale"],"r":1,"e":"L'objectif est d'améliorer le contrôle moteur de la ceinture scapulaire en diminuant l'excès de saillie du bord interne de l'omoplate, afin de prévenir l'aggravation de l'état et les récidives futures (8 semaines).","s":3},{"q":"Quels facteurs liés à l'entraînement doivent être revus avec l'entraîneur ?","o":["La technique des styles et le volume/charge d'entraînement","Le choix du maillot et des lunettes","L'horaire des séances uniquement","La composition de l'équipe"],"r":0,"e":"La technique des styles — amplitudes maximales, abduction et rotation interne maximales augmentant la compression sous-acromiale, faible utilisation des jambes — et le volume/charge d'entraînement doivent être évalués et optimisés avec l'entraîneur.","s":3},{"q":"Quelles sont les quatre questions de la réévaluation ?","o":["Objectifs atteints ? Pronostic à modifier ? Sortie, poursuite ou reformulation ? Nouveau renvoi nécessaire ?","Quelle technique ? Quelle fréquence ? Quel coût ? Quel délai ?","Qui ? Quoi ? Où ? Quand ?","Quelle douleur ? Quelle amplitude ? Quelle force ? Quelle fonction ?"],"r":0,"e":"La réévaluation pose quatre questions : les objectifs sont-ils atteints, le pronostic doit-il être modifié, faut-il envisager la sortie, la poursuite ou la reformulation du plan, et un nouveau renvoi est-il nécessaire ?","s":3},{"q":"Les quatre questions posées pour planifier l'examen objectif dans ce cas sont :","o":["Quel mécanisme de douleur, quelles sources possibles, quels facteurs aggravants, quelles restrictions d'activité et de participation","Quel diagnostic, quel pronostic, quel traitement, quelle durée","Quels tests, dans quel ordre, avec quel matériel, à quelle fréquence","Quelle pathologie, quelle imagerie, quel spécialiste, quel délai"],"r":0,"e":"Cette grille organise tout le raisonnement du dossier : elle oriente le choix des tests avant de les réaliser, au lieu de tester au hasard.","s":3},{"q":"Parmi les sources tissulaires envisagées, la bourse sous-acromiale est suspectée d'être irritée par :","o":["Un conflit fonctionnel pendant la phase aérienne du papillon et l'instabilité passive gléno-humérale","Une bursite infectieuse","Un traumatisme direct","Une calcification"],"r":0,"e":"L'imagerie étant négative, toutes les sources retenues sont fonctionnelles et non structurelles : bourse, longue portion du biceps, coiffe, stabilisateurs scapulaires, capsule.","s":3},{"q":"Les muscles stabilisateurs de l'omoplate cités comme sources possibles sont :","o":["Le deltoïde et le supra-épineux","Le grand dentelé, le trapèze moyen et le trapèze inférieur","Le grand pectoral et le grand dorsal","Le biceps et le triceps"],"r":1,"e":"Leur dysfonctionnement est attribué à la fatigue et à l'instabilité dynamique — ce qui rejoint le fil rouge du dossier, le défaut de contrôle scapulaire.","s":3},{"q":"Concernant la technique de nage, le facteur aggravant identifié est :","o":["Une amplitude insuffisante","Des amplitudes maximales en abduction et rotation interne, augmentant la compression sous-acromiale, avec une faible utilisation des jambes","Une fréquence de mouvement trop lente","Un mauvais alignement de la tête"],"r":1,"e":"Le cours précise que cet aspect doit être évalué et optimisé avec l'entraîneur : il ne relève pas du seul kinésithérapeute.","s":3},{"q":"Le volume d'entraînement est identifié comme facteur aggravant parce que :","o":["La nature « longue distance » induit une plus grande fatigue musculaire","Les séances sont trop courtes","L'intensité est trop faible","Le nombre de compétitions est insuffisant"],"r":0,"e":"Le plan d'entraînement doit être revu avec l'entraîneur, ce qui fait de l'alliance kiné-athlète-entraîneur une condition explicite du pronostic.","s":3},{"q":"Au niveau participation, le cours souligne que :","o":["Aucune participation n'est affectée","Son identité d'athlète de haut niveau est menacée, avec un impact psychosocial à long terme si la stagnation de deux ans n'est pas inversée","Seule sa scolarité est touchée","Sa vie familiale est perturbée"],"r":1,"e":"C'est un rappel que la participation n'est pas une simple liste d'activités : elle engage la place et l'identité de la personne.","s":3},{"q":"Le fait que la douleur persiste deux jours après une aggravation a pour conséquence :","o":["Un risque infectieux","Une limitation de la fréquence des entraînements consécutifs de haute intensité, nuisant à la progression technique","Une contre-indication à toute activité","Un besoin d'imagerie"],"r":1,"e":"Cette latence est un élément de raisonnement décisif : elle relie directement un paramètre symptomatique à une conséquence sur la performance.","s":3},{"q":"L'observation posturale de cette nageuse retrouve :","o":["Une légère rotation interne et antéversion des épaules, avec cyphose dorsale et lordose lombaire accrues","Une scoliose structurale","Un genu valgum","Une asymétrie de longueur des membres"],"r":0,"e":"Le cours précise que ce profil est typique chez les nageurs, ce qui invite à la prudence : une posture fréquente dans une population n'est pas nécessairement la cause des symptômes.","s":3},{"q":"La rotation interne gléno-humérale a été évaluée :","o":["Uniquement à 90°","À 45°, à 90° et à l'amplitude maximale","En passif uniquement","Avec un goniomètre électronique"],"r":1,"e":"Les amplitudes sont normales à 45° et 90°, avec un inconfort à la pression supplémentaire aux amplitudes maximales seulement.","s":3},{"q":"L'hyperextension d'épaule chez cette patiente est :","o":["Limitée et douloureuse","Normale, avec augmentation de la saillie du bord interne de l'omoplate bilatérale, sans douleur","Impossible","Douloureuse à droite uniquement"],"r":1,"e":"Cette saillie du bord interne réapparaît dans tous les mouvements testés : c'est la constante du dossier.","s":3},{"q":"Le dépistage cervical dans ce cas :","o":["N'a pas été réalisé","Est négatif, les amplitudes cervicales actives et passives étant normales et indolores","Est positif","A nécessité une IRM"],"r":1,"e":"La colonne cervicale figurait pourtant parmi les sources possibles envisagées : le dépistage permet précisément de l'écarter.","s":3},{"q":"Le test isométrique des rotateurs à 90° montre :","o":["Une douleur vive en rotation interne","Une absence de douleur mais une force nettement réduite en rotation externe","Une force normale dans les deux sens","Une impossibilité de contraction"],"r":1,"e":"L'interprétation du cours : pas de tendinopathie douloureuse, mais un déficit de force des stabilisateurs postérieurs — cible directe du renforcement.","s":3},{"q":"L'end-feel de l'épaule aux amplitudes passives est décrit comme :","o":["Dur et osseux","Lâche dans toutes les directions, sans douleur, pire à droite","Élastique et douloureux","Bloqué précocement"],"r":1,"e":"Cette sensation de fin de course confirme l'instabilité passive, en cohérence avec l'hypermobilité mesurée en flexion et en abduction.","s":3},{"q":"Le test du quadrant inférieur est positif et se modifie ainsi :","o":["Aggravé par la compression, amélioré par la distraction","Amélioré par la compression, aggravé par la distraction","Insensible aux manœuvres","Positif uniquement à droite"],"r":1,"e":"C'est un argument fort pour une origine capsulaire : la compression stabilise l'articulation, la distraction met la capsule en tension et réveille les symptômes.","s":3},{"q":"Le test push-pull dans ce dossier est :","o":["Négatif","Positif en postérieur, avec léger inconfort","Positif en antérieur","Non réalisable"],"r":1,"e":"Associé au test d'appréhension positif en antérieur, il documente une instabilité multidirectionnelle plutôt qu'une atteinte unidirectionnelle.","s":3},{"q":"L'examen scapulo-thoracique actif et passif montre :","o":["Une raideur marquée","Une hypermobilité dans tous les mouvements, avec augmentation de la proéminence du bord interne — dyskinésie scapulaire","Des amplitudes normales","Un blocage en sonnette externe"],"r":1,"e":"La dyskinésie scapulaire est la traduction observable du défaut de contrôle moteur, qui constitue avec l'hypermobilité la cause retenue.","s":3},{"q":"La palpation retrouve des points sensibles :","o":["Dans le deltoïde antérieur","Dans le ventre de l'infra-épineux et du petit rond","Sur l'acromion","Dans le grand pectoral"],"r":1,"e":"Ce sont précisément les rotateurs externes, dont le testing isométrique montrait une force nettement réduite : la surcharge et le déficit se recoupent.","s":3},{"q":"Dans le cadre CIF de ce cas, les facteurs environnementaux retenus sont :","o":["L'âge et le sexe","Les exigences élevées, l'environnement compétitif avec peu de repos et les gestes répétitifs en amplitudes extrêmes","La vie avec ses parents","Le parcours scolaire"],"r":1,"e":"Ses 16 ans, son sexe, son statut d'étudiante et sa composition familiale relèvent des facteurs personnels.","s":3},{"q":"Le tableau physiopathologique de ce cas se referme sur une boucle où :","o":["La douleur guérit spontanément","La détérioration émotionnelle aggrave en retour le tableau, entretenue par un environnement compétitif peu reposant","L'imagerie devient positive","La performance s'améliore"],"r":1,"e":"Cette circularité justifie d'intervenir sur plusieurs points à la fois : la douleur, le contrôle moteur, la charge d'entraînement et le vécu de l'athlète.","s":3},{"q":"Le pronostic de ce cas s'appuie sur une source documentaire :","o":["Postiaux, 1999","StatPearls, Swimmer's Shoulder, 2023","Kahneman, 2011","Hall et Brody, 1999"],"r":1,"e":"Rattacher le pronostic à une référence explicite illustre la dimension « meilleures preuves » du modèle, à côté de l'expertise clinique et des attentes du patient.","s":3},{"q":"Quel territoire vasculaire est atteint chez Teresa Costa ?","o":["L'artère cérébrale antérieure gauche","L'artère cérébrale moyenne droite","L'artère cérébrale postérieure","Le tronc basilaire"],"r":1,"e":"La TDM-C révèle des lésions hypodenses fronto-pariétales droites, avec séquelle d'AVC au niveau de l'artère cérébrale moyenne droite.","s":4},{"q":"Quelle est la prédominance de l'hémiparésie de Teresa ?","o":["Crurale","Brachiale","Faciale","Proximale bilatérale"],"r":1,"e":"Elle présente une hémiparésie gauche à prédominance brachiale, esquissant déjà une activité motrice aux deux membres.","s":4},{"q":"Quels sont les sous-scores STREAM de Teresa ?","o":["MI 11/20 et MS 8/20","MI 8/20 et MS 11/20","MI 15/20 et MS 15/20","MI 20/20 et MS 0/20"],"r":0,"e":"Le sous-score STREAM du membre inférieur est de 11/20 et celui du membre supérieur de 8/20.","s":4},{"q":"Quels sont les résultats du MINIBESTest et du Berg chez Teresa ?","o":["MINIBESTest 14 et Berg 30/56","MINIBESTest 0 et Berg 7/56","MINIBESTest 28 et Berg 56/56","MINIBESTest 7 et Berg 0/56"],"r":1,"e":"Le MINIBESTest est à 0 et l'échelle de Berg à 7/56, traduisant une atteinte majeure de l'équilibre.","s":4},{"q":"Que signifie un score MIF de 60/126 chez cette patiente ?","o":["Une indépendance complète","Une dépendance modifiée, avec participation de l'individu à environ 25 % de la tâche","Une dépendance totale","Une indépendance avec aide technique"],"r":1,"e":"La MIF à 60/126 correspond à une dépendance modifiée : la participation de l'individu représente environ 25 % de la tâche.","s":4},{"q":"Comment se répartit le déficit sensoriel chez Teresa ?","o":["Anesthésie superficielle et profonde distale, hypoesthésie modérée en proximal et central","Anesthésie complète de tout l'hémicorps","Hypoesthésie distale seulement","Sensibilité normale"],"r":0,"e":"Il existe une anesthésie superficielle et profonde au niveau distal des membres gauches, et une hypoesthésie modérée au niveau proximal et central.","s":4},{"q":"Que se passe-t-il quand Teresa perd l'appui de sa main droite en position assise ?","o":["Elle maintient la position sans difficulté","Elle tend à tomber du côté gauche, faute d'ajustements posturaux du tronc et du bassin","Elle tombe vers l'avant","Elle se rattrape avec le membre gauche"],"r":1,"e":"Sans l'appui de la main, elle tend à tomber du côté gauche puisqu'elle ne présente pas les ajustements posturaux nécessaires au niveau du tronc et du bassin pour s'adapter à la gravité ou à des stimuli externes minimes.","s":4},{"q":"Quelle réaction associée apparaît chez Teresa lors de l'activité ?","o":["Une extension du coude et des doigts","Une légère flexion du coude et des doigts du MS gauche","Une abduction de l'épaule droite","Une extension du genou gauche"],"r":1,"e":"L'activité déclenche une légère réaction associée au niveau du MS gauche selon un schéma de légère flexion du coude et des doigts ; en tentant de se stabiliser, elle augmente la fixation de l'hémicorps droit.","s":4},{"q":"Quelle structure de la CIF correspond au cortex fronto-pariétal droit ?","o":["Les structures","Les fonctions","L'activité","La participation"],"r":0,"e":"Dans le cadre CIF du cas, le cortex fronto-pariétal droit figure sous la rubrique Structures ; les déficits de contrôle postural, de force et de sensibilité relèvent des Fonctions.","s":4},{"q":"Quels facteurs environnementaux sont identifiés chez Teresa ?","o":["Une famille coopérante (+) et des barrières architecturales (−)","Un logement adapté et une aide professionnelle","Une absence totale de soutien","Un milieu professionnel favorable"],"r":0,"e":"Les facteurs environnementaux sont la famille coopérante, facilitateur, et les barrières architecturales, barrière ; les facteurs personnels sont d'être en bonne santé et active.","s":4},{"q":"Quelle voie explique principalement la faiblesse hémicorporelle dans l'AVC ?","o":["La voie cortico-réticulo-spinale","La voie cortico-spinale latérale","La voie spinothalamique","Le faisceau gracile"],"r":1,"e":"La voie cortico-spinale latérale explique l'hémiparésie ; les voies cortico-spinale médiale et cortico-réticulo-spinale expliquent la baisse des ajustements posturaux anticipatoires et de la planification du mouvement.","s":4},{"q":"Quel signe relève de l'atteinte du cortex pariétal dans ce cas ?","o":["L'hyperréflexie","L'astéréognosie et la diminution de la représentation de l'hémicorps gauche","La faiblesse du membre inférieur","La réaction associée"],"r":1,"e":"L'atteinte du cortex somatosensoriel primaire et des aires d'association pariétales entraîne une baisse de la localisation sensorielle, de la représentation de l'hémicorps gauche, de l'image corporelle et une astéréognosie.","s":4},{"q":"Comment se formule le problème réel principal concernant le MS gauche ?","o":["Faiblesse isolée du membre supérieur","Altération du contrôle moteur du MSG (STREAM 8/20), conditionnant la fonctionnalité dans les soins personnels, la mobilité au lit, les transferts et le maintien assis","Réaction associée du membre supérieur","Anesthésie distale"],"r":1,"e":"Le problème est formulé avec sa conséquence fonctionnelle et ses causes : faiblesse musculaire chiffrée, altération de l'alignement scapulaire, réaction associée, altérations sensorielles et diminution de l'activation du core.","s":4},{"q":"Quels sont les trois problèmes potentiels identifiés dans le cas de l'AVC ?","o":["Altérations non neurales, cycle d'inactivité avec déconditionnement, et lésion cutanée ou articulaire de l'hémicorps gauche","Récidive d'AVC, épilepsie et aphasie","Thrombose veineuse, embolie et infection","Dépression, anxiété et troubles du sommeil"],"r":0,"e":"Les trois problèmes potentiels sont le risque d'altérations non neurales, le risque de cycle d'inactivité avec déconditionnement cardio-respiratoire et faiblesse, et le risque de lésion cutanée et/ou myofasciale et articulaire de l'hémicorps gauche — l'épaule douloureuse.","s":4},{"q":"Quels sont les quatre niveaux emboîtés du diagnostic kinésithérapique en neurologie ?","o":["Activité/participation, structure/fonction, tableau neuro-moteur et condition clinique","Examen, évaluation, diagnostic et pronostic","Force, sensibilité, équilibre et fonction","Structures, fonctions, activités et participation"],"r":0,"e":"Le diagnostic s'organise en quatre niveaux emboîtés : ACTIVITÉ/PARTICIPATION, STRUCTURE/FONCTION, TABLEAU NEURO-MOTEUR et CONDITION CLINIQUE.","s":4},{"q":"Sur quelles trois entrées repose le pronostic dans ce cours ?","o":["Caractéristiques du patient, évidence scientifique et expérience professionnelle","Âge, sexe et comorbidités","Imagerie, biologie et clinique","Durée, coût et faisabilité"],"r":0,"e":"Le pronostic clinique se construit au croisement des caractéristiques du patient, de l'évidence scientifique et de l'expérience professionnelle.","s":4},{"q":"Quel objectif chiffré est fixé pour le MS gauche de Teresa ?","o":["Passer de 8 à 14 points au sous-score STREAM en 6 semaines","Passer de 8 à 20 points en 4 semaines","Atteindre le grade 5 de force en 6 semaines","Récupérer la marche en 6 semaines"],"r":0,"e":"L'objectif est d'améliorer le contrôle moteur et sensoriel du MSG, passant de 8 à 14 points au sous-score de la STREAM, afin de devenir plus autonome au quotidien, en 6 semaines.","s":4},{"q":"Quelle est la cause de la lésion médullaire chez Helena Sousa ?","o":["Un traumatisme routier","Une tumeur osseuse du corps de T10 avec sténose du canal vertébral, opérée","Une hernie discale","Une infection médullaire"],"r":1,"e":"Une tumeur osseuse a été identifiée au niveau du corps de T10, avec sténose du canal vertébral et atteinte médullaire ; elle a été opérée pour ablation, sans pose de matériel de fixation.","s":4},{"q":"Quel est le tableau clinique de sortie d'Helena ?","o":["Tétraplégie complète ASIA A","Paraplégie incomplète ASIA C, niveau T10","Paraplégie complète ASIA A","Syndrome de Brown-Séquard"],"r":1,"e":"Le compte rendu de sortie indique une paraplégie incomplète ASIA C, de niveau T10.","s":4},{"q":"Quel est le score SCIM d'Helena à l'examen ?","o":["39/100","56/100","65/100","100/100"],"r":0,"e":"Le SCIM est à 39/100 ; les objectifs visent ensuite une progression de 56/100 à 65/100 en 4 semaines.","s":4},{"q":"Quel est le grade de force des MS chez Helena ?","o":["Grade 0 à 1","Grade 2","Majoritairement grade 3+","Grade 5"],"r":2,"e":"Aux membres supérieurs, la majorité des groupes musculaires présente un grade de force de 3+, alors que les MI sont globalement à 0 ou 1.","s":4},{"q":"Quelle est la caractéristique de la cicatrice d'Helena ?","o":["Chéloïde et inflammatoire","D'environ 10 cm, de bonne coloration et cicatrisation, mais avec un déficit de mobilité aux 2/3 supérieurs et un inconfort EVA 2/10","Infectée et suintante","Totalement mobile et indolore"],"r":1,"e":"La cicatrice dorsale mesure environ 10 cm, est de bonne coloration et cicatrisation, mais présente un déficit de mobilité aux 2/3 supérieurs limitant le glissement longitudinal et transversal, avec un léger inconfort à 2/10.","s":4},{"q":"Quelle est la stratégie posturale habituelle d'Helena en position assise ?","o":["Un appui dorsal","La fixation des mains au bord du lit avec une attitude de fixation globale des MS","Un maintien actif du tronc","Une aide humaine permanente"],"r":1,"e":"Elle prend la position assise avec fixation des mains au bord du lit et une attitude de fixation globale des membres supérieurs, ce qui est sa stratégie posturale habituelle.","s":4},{"q":"Quel facteur non moteur est intégré comme cause du déficit de contrôle postural chez Helena ?","o":["La douleur","La peur","La fatigue","La dénutrition"],"r":1,"e":"La peur est explicitement intégrée comme cause du problème réel « diminution du contrôle postural assis », aux côtés des déficits moteurs, sensoriels et de la mobilité cicatricielle.","s":4},{"q":"Quels sont les six axes de l'examen objectif retenus pour la lésion médullaire ?","o":["Force et sensibilité au-dessus et au-dessous, contrôle postural, fonctionnalité, mobilité de la cicatrice et fonction respiratoire","Force, amplitude, réflexes, tonus, marche et équilibre","Imagerie, biologie, clinique, fonction, douleur et qualité de vie","Observation, palpation, percussion, auscultation, tests et examens"],"r":0,"e":"Les axes cités sont : force au-dessus et au-dessous de la lésion, sensibilité au-dessus et au-dessous, contrôle postural et équilibre assis, fonctionnalité, mobilité de la cicatrice et fonction respiratoire.","s":4},{"q":"Pour quelles activités Helena a-t-elle besoin d'une aide TOTALE ?","o":["Pour les déplacements en fauteuil à domicile","Pour la mobilité de base : mobilité au lit, transfert décubitus dorsal-assis et transferts vers le fauteuil","Pour l'habillage du haut du corps","Pour la communication"],"r":1,"e":"Elle nécessite une aide totale pour la mobilité de base : mobilité au lit, transfert du décubitus dorsal à assis et transferts lit / autres surfaces vers le fauteuil roulant.","s":4},{"q":"Quel est le risque potentiel lié à l'immobilité et au déficit sensoriel sous la lésion ?","o":["Le risque de développer des escarres de pression","Le risque de spasticité","Le risque de thrombose","Le risque d'infection urinaire"],"r":0,"e":"Le risque de développer des escarres de pression est dû à l'immobilité et à l'augmentation de la pression prolongée, consécutives à la faiblesse marquée et au déficit sensoriel sous le niveau de la lésion.","s":4},{"q":"Quel objectif est fixé avec le délai le plus court dans le cas de la lésion médullaire ?","o":["Améliorer la mobilité de la cicatrice aux 2/3 supérieurs en 10 jours","Améliorer le contrôle postural assis en 4 semaines","Assurer l'éducation de la patiente et de la famille en 1 semaine","Augmenter la force des MI en 4 semaines"],"r":2,"e":"L'éducation de la patiente, de la famille et des aidants est fixée à 1 semaine ; la mobilité de la cicatrice à 10 jours et les objectifs de contrôle moteur à 4 semaines.","s":4},{"q":"Quel est le but explicite de l'éducation de la patiente et de la famille ?","o":["Réduire la durée d'hospitalisation","Prévenir les escarres, combattre l'immobilité et le non-usage, et prévenir une manipulation en désalignement et un traumatisme","Diminuer le coût du traitement","Assurer l'observance médicamenteuse"],"r":1,"e":"L'éducation vise à prévenir le développement d'escarres de pression, à combattre l'immobilité et le non-usage et les altérations non neurales qui en découlent, et à prévenir une manipulation en désalignement et un possible traumatisme.","s":4},{"q":"Quels éléments figurent dans l'entraînement fonctionnel du plan d'intervention ?","o":["Mobilité au lit, push-ups, transferts et mobilité au fauteuil roulant","Marche sur tapis, escaliers et course","Exercices en piscine et vélo","Travail du membre supérieur uniquement"],"r":0,"e":"L'entraînement fonctionnel comprend la mobilité au lit, les push-ups, les transferts et la mobilité au fauteuil roulant, aux côtés de l'entraînement de l'équilibre assis progressif, de l'entraînement aérobie et de l'entraînement de la position debout.","s":4},{"q":"Le tableau physiopathologique en neurologie s'organise dans ce cours en trois colonnes :","o":["Physiopathologie de la maladie, signes et symptômes chez la patiente, données de l'évaluation","Structure, fonction, participation","Diagnostic, pronostic, traitement","Examen, évaluation, intervention"],"r":0,"e":"C'est ce schéma qui relie la lésion anatomique aux chiffres mesurés : il évite que l'évaluation reste une collection de scores sans explication.","s":4},{"q":"Chez Teresa, l'atteinte du cortex frontal compromet la voie cortico-spinale latérale, ce qui produit :","o":["Une astéréognosie","L'hémiparésie gauche","Une perte de l'image corporelle","Un déficit de localisation sensorielle"],"r":1,"e":"Les voies cortico-spinale médiale et cortico-réticulo-spinale sont responsables de la baisse des ajustements posturaux anticipatoires et de la planification du mouvement.","s":4},{"q":"Les ajustements posturaux anticipatoires (APA), altérés dans ce cas, dépendent :","o":["De la voie cortico-spinale latérale","Des voies cortico-spinale médiale et cortico-réticulo-spinale","Du cortex somatosensoriel primaire","Du cervelet uniquement"],"r":1,"e":"Leur déficit explique qu'elle ne s'adapte ni à la gravité ni à des stimuli externes minimes en position assise, et qu'elle compense par une fixation manuelle.","s":4},{"q":"L'astéréognosie, conséquence de l'atteinte pariétale, correspond à :","o":["Une incapacité à reconnaître un objet par le toucher","Une paralysie des doigts","Une perte de la vision","Une difficulté d'élocution"],"r":0,"e":"Elle s'associe à la baisse de localisation sensorielle, à la réduction de la représentation de l'hémicorps gauche et à l'altération de la relation à l'espace extracorporel.","s":4},{"q":"Le déficit sensoriel pariétal aggrave le déficit moteur parce qu'il :","o":["Provoque une douleur","Prive le mouvement de feedback","Augmente la spasticité","Réduit la force musculaire"],"r":1,"e":"Le cours l'écrit explicitement : manque de feedback, donc aggravation du déficit fonctionnel du membre supérieur. Commander sans percevoir le résultat rend le contrôle impossible.","s":4},{"q":"Chez Teresa, la tentative d'atteinte avec le membre supérieur gauche se fait selon un schéma :","o":["De rotation externe et adduction","De rotation interne et abduction de l'épaule, flexion du coude et légère flexion des doigts","D'extension complète","Normal mais ralenti"],"r":1,"e":"Ce schéma stéréotypé est caractéristique : il traduit la perte de sélectivité et le recours à des synergies globales plutôt qu'à un mouvement analytique.","s":4},{"q":"Le grade de force des extenseurs du coude gauche chez Teresa est :","o":["0","1","2","3"],"r":1,"e":"Détail complet : fléchisseurs de l'épaule 2−, fléchisseurs du coude 2, extenseurs du coude 1, extenseurs du poignet et des doigts 1. L'objectif est de passer chacun d'un grade.","s":4},{"q":"Au membre inférieur gauche, les fléchisseurs dorsaux de Teresa sont cotés :","o":["Grade 0","Grade 2","Grade 3","Grade 4"],"r":1,"e":"Extenseurs et abducteurs de hanche et extenseurs du genou sont à 3. La tentative d'activation se fait avec une instabilité proximale évidente.","s":4},{"q":"Concernant la performance fonctionnelle, Teresa nécessite une aide totale pour :","o":["Les soins personnels","La mobilité au lit","Les transferts","La locomotion"],"r":3,"e":"Elle nécessite une aide modérée pour les soins personnels, la mobilité au lit et les transferts ; seule la locomotion exige une aide totale.","s":4},{"q":"Dans le cadre CIF de ce cas, « famille coopérante » et « barrières architecturales » sont notés :","o":["Comme facteurs environnementaux, respectivement facilitateur et barrière","Comme facteurs personnels","Comme fonctions du corps","Comme restrictions de participation"],"r":0,"e":"Les facteurs personnels retenus sont « en bonne santé » et « active ». La double notation facilitateur/barrière est propre aux facteurs environnementaux.","s":4},{"q":"Au niveau participation, le cours retient chez Teresa l'incapacité :","o":["À se nourrir","À exercer sa profession et à maintenir une vie sociale et familiale","À communiquer","À se laver"],"r":1,"e":"Les difficultés dans les activités de la vie quotidienne relèvent, elles, du niveau activité. La distinction entre les deux niveaux structure tout le diagnostic.","s":4},{"q":"Parmi les causes du problème réel concernant le membre supérieur gauche, le cours retient notamment :","o":["Une diminution de l'activation musculaire du core","Une atteinte cérébelleuse","Une raideur articulaire préexistante","Une douleur neuropathique"],"r":0,"e":"S'y ajoutent la faiblesse chiffrée groupe par groupe, l'altération de l'alignement scapulaire, la réaction associée en activité et les troubles sensitifs.","s":4},{"q":"Le risque d'épaule douloureuse de l'hémiplégique est rapporté dans ce cas :","o":["À la spasticité seule","Au déficit sensoriel et à la faiblesse","À une lésion tendineuse préexistante","À la rééducation"],"r":1,"e":"Il figure parmi les problèmes potentiels, avec le risque de lésion cutanée et d'atteinte myofasciale ou articulaire de l'hémicorps gauche.","s":4},{"q":"Le risque d'altérations non neurales chez Teresa est attribué à :","o":["La réaction associée du MSG, le maintien prolongé en position assise et les compensations","Une carence nutritionnelle","Un traitement médicamenteux","L'âge de la patiente"],"r":0,"e":"Ces altérations touchent les longueurs musculaires et la mobilité articulaire : elles s'ajoutent au déficit neurologique et sont, elles, largement évitables.","s":4},{"q":"L'objectif principal fixé pour le membre supérieur gauche de Teresa est :","o":["Passer de 8 à 14 points au sous-score STREAM en 6 semaines","Atteindre 20/20 en 4 semaines","Récupérer une force grade 5","Supprimer la réaction associée en 2 semaines"],"r":0,"e":"Sa finalité est explicitement fonctionnelle : devenir plus autonome au quotidien. Il se décline ensuite en cinq sous-objectifs.","s":4},{"q":"Parmi les sous-objectifs déclinés pour Teresa figure :","o":["Favoriser une plus grande activation du core dans les activités du membre supérieur","La reprise de la conduite","Le retour au travail","La marche autonome"],"r":0,"e":"Les autres : augmenter la force groupe par groupe en 4 semaines, réaligner les structures de l'épaule, diminuer la réaction associée et normaliser la sensibilité.","s":4},{"q":"Le pronostic en neurologie se construit, selon ce cours, au croisement de :","o":["Caractéristiques du patient, évidence scientifique et expérience professionnelle","Imagerie, biologie et clinique","Âge, sexe et comorbidités","Famille, équipe et institution"],"r":0,"e":"On retrouve les trois cercles du modèle général, transposés au pronostic : ni les seules données du patient, ni la seule littérature ne suffisent.","s":4},{"q":"Chez Helena, la lésion médullaire résulte :","o":["D'un traumatisme routier","D'une tumeur osseuse du corps de T10 avec sténose du canal et atteinte médullaire","D'une hernie discale","D'une infection"],"r":1,"e":"Elle a été opérée pour ablation, sans pose de matériel de fixation, et sort avec une paraplégie incomplète ASIA C de niveau T10.","s":4},{"q":"Le premier signe ayant conduit Helena à consulter était :","o":["Une douleur dorsale aiguë","Une apparition progressive de faiblesse et de paresthésies aux deux membres inférieurs","Une perte de connaissance","Une incontinence brutale"],"r":1,"e":"Le caractère progressif oriente d'emblée vers un processus compressif lent, à la différence d'un traumatisme ou d'un accident vasculaire médullaire.","s":4},{"q":"Helena est vue en kinésithérapie :","o":["Immédiatement après la chirurgie","6 semaines après la chirurgie, à domicile depuis 4 semaines","6 mois après","Un an après"],"r":1,"e":"Sa situation est stabilisée sur le plan chirurgical et oncologique : elle doit commencer immédiatement la kinésithérapie, sans restrictions particulières.","s":4}]};
